package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"runtime/debug"
	"sync/atomic"
	"time"

	"github.com/entireio/go-nuts"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/internal/natslog"
	"github.com/entirehq/mirror-pipeline/pkg/donejobs"
	"github.com/entirehq/mirror-pipeline/pkg/failindex"
	"github.com/entirehq/mirror-pipeline/pkg/gitjobs"
	"github.com/entireio/go-nuts/natsmsg"
)

const (
	consumerFailureDelay = 30 * time.Second
	consumerMaxDeliver   = 10
	consumerAckWait      = 15 * time.Minute
	consumerBackoffInit  = 1 * time.Second
	consumerBackoffMax   = 30 * time.Second
	// consumerInProgressInterval paces in-progress ack extensions while a
	// long sync is running. Derived from consumerAckWait so any change to
	// the ack budget automatically widens the extension cadence; /3 gives
	// two extension attempts within one ack window before redelivery.
	consumerInProgressInterval = consumerAckWait / 3
	// defaultSyncTimeout bounds one sync attempt end-to-end (override via
	// ENTIRE_WORKER_SYNC_TIMEOUT; "0" disables). The git smart-HTTP client
	// has no timeout of its own, and the InProgress extender refreshes the
	// ack deadline for as long as sync runs — so without this budget a
	// black-holed connection (established, then silently dropped) wedges
	// the replica forever AND suppresses redelivery: the serial consume
	// loop never fetches again and the extender keeps the message owned.
	// Generous on purpose: a legitimate multi-GB initial clone must fit.
	defaultSyncTimeout = 30 * time.Minute
)

type repoSyncer interface {
	sync(ctx context.Context, req syncRequest) error
}

// ackableMsg is the subset of *nats.Msg the disposition logic uses to ack a
// message. A seam so the Term/Nak/Ack decisions are unit-testable without a
// live JetStream subscription (*nats.Msg satisfies it implicitly).
type ackableMsg interface {
	Ack(opts ...nats.AckOpt) error
	Term(opts ...nats.AckOpt) error
	NakWithDelay(delay time.Duration, opts ...nats.AckOpt) error
	Metadata() (*nats.MsgMetadata, error)
}

// failureIndex is the failure-index surface the consumer depends on. An
// interface so a test can inject a fake whose RecordFailure errors, locking the
// fail-open invariant — a KV write failure must Term (not Nak) and surface via
// record_failed{cause} (*failindex.Index satisfies it).
type failureIndex interface {
	RecordFailure(ulid string, fs failindex.FailedSync, seq uint64, now time.Time) (recorded bool, err error)
	RecordNoopCompletionFailure(ulid string, fs failindex.FailedSync, seq uint64, now time.Time) (bool, error)
	ClearOnSuccess(ulid string, successSeq uint64) (bool, error)
	ClearOnCompletion(ulid string, successSeq uint64) (bool, error)
}

// completionPublisher publishes a terminal mirror-completion (the mirror_done
// op on the in-cell repo_ops_v1 stream) so the co-located regional entire-core
// can flip mirror_repos.status (processing → ready|failed). An interface so the
// disposition logic stays unit-testable without a live JetStream, and so a
// nil publisher degrades to the pre-completion behaviour (*donejobs.Publisher
// satisfies it).
type completionPublisher interface {
	PublishCompletion(ctx context.Context, jurisdiction, cluster string, job donejobs.Job) error
}

type consumer struct {
	subscription        subscriptionConfig
	subscribed          atomic.Bool
	drain               consumerDrain
	js                  nats.JetStreamContext
	clusterID           string
	jurisdiction        string
	sourceClusterDomain string
	syncer              repoSyncer
	metrics             *workerMetrics
	// health drives the severity of subscribe/fetch failure logs: recoverable
	// interruptions log at warn until the loop goes too long without progress.
	health natslog.Health
	// failidx is the mirror-sync failure index (KV). nil when the bucket could
	// not be bound at startup — the record/clear helpers then degrade to the
	// pre-index behaviour (bare Term / no clear) so the worker still syncs.
	failidx failureIndex
	// donePub publishes terminal mirror-completion events (repo_ops_v1 mirror_done op).
	// nil when no publisher is wired (degrades to the pre-completion
	// behaviour: ack/term as before, entire-core never learns the outcome).
	donePub completionPublisher
	// positions snapshots an entiredb source's write position before the
	// fetch, so ready completions can carry the applied-watermark evidence
	// (ADR 20260818-native-mirror-resync-sweep). nil when the svctok mTLS
	// transport isn't configured — completions then carry position 0 ("no
	// evidence") and the control plane stamps nothing.
	positions positionSnapshotter
	// syncTimeout bounds one sync attempt (see defaultSyncTimeout). <= 0
	// disables the budget.
	syncTimeout time.Duration
}

// mirrorConsumerDurable is the JetStream durable name the worker subscribes
// to. KEDA's nats-jetstream scaler targets the same name (the `consumer:`
// field in the mirror-worker ScaledObjects in fleet) so the autoscaling
// signal reflects exactly this worker's backlog.
func mirrorConsumerDurable(jurisdiction, clusterID string) string {
	return fmt.Sprintf("mirror-git-v1-%s-%s", jurisdiction, clusterID)
}

func (c *consumer) run(ctx context.Context) {
	c.runSubscription(ctx, c.subscription)
}

// The durable belongs to the deployment, never to a process subscription.
// Explicit creation followed by Bind prevents Unsubscribe from deleting a
// durable that this process happened to create (including on shutdown).
func (c *consumer) subscribe(cfg subscriptionConfig) (*nats.Subscription, error) {
	info, err := c.js.ConsumerInfo(gitjobs.StreamName, cfg.durable)
	if errors.Is(err, nats.ErrConsumerNotFound) {
		info, err = c.js.AddConsumer(gitjobs.StreamName, &nats.ConsumerConfig{
			Durable: cfg.durable, FilterSubject: cfg.subject, DeliverPolicy: nats.DeliverAllPolicy,
			AckPolicy: nats.AckExplicitPolicy, AckWait: consumerAckWait, MaxDeliver: consumerMaxDeliver,
		})
	}
	if err != nil {
		return nil, err
	}
	actual := info.Config
	if actual.FilterSubject != cfg.subject || len(actual.FilterSubjects) != 0 || actual.DeliverPolicy != nats.DeliverAllPolicy || actual.AckPolicy != nats.AckExplicitPolicy || actual.AckWait != consumerAckWait || actual.MaxDeliver != consumerMaxDeliver || len(actual.BackOff) != 0 {
		return nil, fmt.Errorf("consumer %s has incompatible routing/delivery configuration; refusing to modify it", cfg.durable)
	}

	return c.js.PullSubscribe(cfg.subject, cfg.durable, nats.Bind(gitjobs.StreamName, cfg.durable), nats.ManualAck())
}

func (c *consumer) runSubscription(ctx context.Context, cfg subscriptionConfig) {
	backoff := consumerBackoffInit

	for {
		if ctx.Err() != nil {
			return
		}
		sub, err := c.subscribe(cfg)
		if err != nil {
			c.health.SubscribeErr(ctx, "Failed to subscribe", err,
				slog.String("subject", cfg.subject),
				slog.String("durable", cfg.durable),
			)
			select {
			case <-ctx.Done():
				return
			case <-time.After(backoff):
				backoff = min(backoff*2, consumerBackoffMax)
				continue
			}
		}
		backoff = consumerBackoffInit
		slog.Info("Consumer subscribed", slog.String("durable", cfg.durable), slog.String("subject", cfg.subject))

		c.subscribed.Store(true)
		c.consumeLoop(ctx, sub)
		c.subscribed.Store(false)
		_ = sub.Unsubscribe()

		if ctx.Err() != nil {
			return
		}
	}
}

func (c *consumer) consumeLoop(ctx context.Context, sub *nats.Subscription) {
	for ctx.Err() == nil {
		// Admission covers the outstanding Fetch AND all its handlers. A drain
		// cannot report completion while a fetch could still deliver a new job.
		if !c.drain.begin() {
			<-ctx.Done()
			return
		}
		err := c.consumeBatch(ctx, sub)
		c.drain.finish()
		if err != nil {
			return
		}
	}
}

func (c *consumer) consumeBatch(ctx context.Context, sub *nats.Subscription) error {
	msgs, err := sub.Fetch(1, nats.MaxWait(5*time.Second))
	if err != nil {
		if errors.Is(err, nats.ErrTimeout) {
			c.health.Recovered()
			return nil
		}
		if !nuts.IsShutdownFetchErr(ctx, err) {
			c.health.Err(ctx, "Fetch error", err)
		}
		return err
	}
	c.health.Recovered()
	for _, msg := range msgs {
		c.handleMessage(ctx, msg)
	}
	return nil
}

func (c *consumer) handleMessage(ctx context.Context, msg *nats.Msg) {
	// Parent the consume span to the producer's trace when the publisher
	// injected a W3C traceparent header (pkg/natsmsg.Inject). When headers
	// are absent (older publishers, or the test /publish endpoint), Extract
	// is a no-op and the span starts a new trace.
	ctx = natsmsg.Extract(ctx, msg)

	ctx, span := Tracer().Start(ctx, "mirror.consume",
		trace.WithSpanKind(trace.SpanKindConsumer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "receive"),
			attribute.String("messaging.destination.name", msg.Subject),
		),
	)
	defer span.End()

	// A panic anywhere below (a nil deref in payload handling, a bug deep in
	// the git-sync stack on a pathological repo) must NOT unwind into the
	// consume goroutine: that crashes the process, and because the message was
	// never acked JetStream redelivers it — so every replica that picks it up
	// crashes in turn, turning one poison-pill job into a cluster-wide
	// crash-loop. Recover and dispose it as a transient failure instead.
	// Registered after span.End() so it runs first (LIFO) and can stamp the
	// span before it closes.
	defer func() {
		if r := recover(); r != nil {
			c.handlePanic(ctx, span, msg, r)
		}
	}()

	if meta, err := msg.Metadata(); err == nil {
		span.SetAttributes(
			attribute.Int64("messaging.nats.sequence", int64(meta.Sequence.Stream)),
			attribute.Int64("messaging.nats.delivery_count", int64(meta.NumDelivered)),
		)
	} else {
		slog.DebugContext(ctx, "msg.Metadata failed; span missing nats sequence attrs", slog.Any("error", err))
	}

	// Subject is the canonical routing key — placement, source kind, and op
	// live there, not in the body. A malformed subject means the broker
	// routed something we shouldn't have received; terminate without retry.
	parsed, err := gitjobs.ParseSubject(msg.Subject)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "parse subject")
		span.SetAttributes(attribute.Bool("entire.message.terminated", true))
		slog.ErrorContext(ctx, "Bad subject, terminating", slog.Any("error", err))
		_ = msg.Term()
		return
	}
	span.SetAttributes(parsed.SpanAttrs()...)

	j, err := gitjobs.UnmarshalFor(parsed.SourceKind, msg.Data)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "unmarshal job")
		span.SetAttributes(attribute.Bool("entire.message.terminated", true))
		slog.ErrorContext(ctx, "Bad job payload, terminating", slog.Any("error", err))
		// Terminate WITH the failure-index record + failed-completion publish,
		// not a bare Term: UnmarshalFor returns the decoded body alongside a
		// validation error, so a kind/body mismatch (e.g. a github-shaped body
		// on an entiredb subject) still carries the target ULID that keys the
		// record — the same terminal handling the pre-kind-aware code gave
		// these messages at the source-kind gate. recordTerminal and
		// publishFailed no-op safely on an empty ULID (pure JSON garbage).
		c.terminate(ctx, msg, parsed.SourceKind, j.Target.ULID, msg.Subject, msg.Data, failindex.ReasonValidation, failindex.SourceWorkerValidation, err)
		return
	}
	c.handleGitJob(ctx, span, msg, parsed, j)
}

// handlePanic disposes of a message whose handler panicked. It Naks (rather
// than Terms) so redelivery is bounded by consumerMaxDeliver and the existing
// MAX_DELIVERIES path + advisory backstop still record the eventual terminal
// failure into the index for re-kick: a transient cause recovers on a later
// delivery, and a deterministic one dead-ends — both WITHOUT crashing the
// process. The stack is logged once here (the recover site) so the poison-pill
// payload is diagnosable; the span carries entire.handler.panicked for queries.
func (c *consumer) handlePanic(ctx context.Context, span trace.Span, m ackableMsg, recovered any) {
	err := fmt.Errorf("panic recovered in mirror handler: %v", recovered)
	span.RecordError(err)
	span.SetStatus(otelcodes.Error, "handler panic")
	span.SetAttributes(attribute.Bool("entire.handler.panicked", true))
	slog.ErrorContext(ctx, "Recovered panic in mirror handler; naking message (bounded by MaxDeliver)",
		slog.Any("panic", recovered),
		slog.String("stack", string(debug.Stack())),
	)
	c.metrics.recordPanic(ctx)
	_ = m.NakWithDelay(consumerFailureDelay)
}

func (c *consumer) handleGitJob(ctx context.Context, span trace.Span, msg *nats.Msg, parsed gitjobs.ParsedSubject, j gitjobs.Job) {
	span.SetAttributes(j.SpanAttrs()...)
	logAttrs := append(parsed.LogAttrs(), j.LogAttrs()...)
	slog.LogAttrs(ctx, slog.LevelInfo, "Processing git job", logAttrs...)

	if parsed.Op != gitjobs.OpSyncRepo {
		err := permanentErr(fmt.Errorf("unsupported operation %q", parsed.Op))
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "unsupported operation")
		span.SetAttributes(
			attribute.Bool("entire.error.permanent", true),
			attribute.Bool("entire.message.terminated", true),
		)
		slog.ErrorContext(ctx, "Unsupported operation, terminating", slog.String("operation", string(parsed.Op)))
		c.terminate(ctx, msg, parsed.SourceKind, j.Target.ULID, msg.Subject, msg.Data, failindex.ReasonValidation, failindex.SourceWorkerValidation, err)
		return
	}

	if !c.subscription.acceptsKind(parsed.SourceKind) {
		err := permanentErr(fmt.Errorf("source kind %q is outside worker role %q", parsed.SourceKind, c.subscription.role))
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "wrong worker role")
		c.terminate(ctx, msg, parsed.SourceKind, j.Target.ULID, msg.Subject, msg.Data, failindex.ReasonValidation, failindex.SourceWorkerValidation, err)
		return
	}

	var sreq syncRequest
	// sourcePosition is the entiredb source's pre-fetch write-position
	// snapshot; 0 for GitHub-kind syncs and failed snapshots ("no watermark
	// evidence" — the ready completion then stamps nothing).
	var sourcePosition int64
	switch parsed.SourceKind {
	case gitjobs.SourceKindGithub:
		installationID, err := gitjobs.ParseGithubInstallationAuthRef(j.Source.AuthRef)
		if err != nil {
			err := permanentErr(err)
			span.RecordError(err)
			span.SetStatus(otelcodes.Error, "invalid git source auth ref")
			span.SetAttributes(
				attribute.Bool("entire.error.permanent", true),
				attribute.Bool("entire.message.terminated", true),
			)
			slog.ErrorContext(ctx, "Invalid git source auth ref, terminating", slog.Any("error", err))
			c.terminate(ctx, msg, parsed.SourceKind, j.Target.ULID, msg.Subject, msg.Data, failindex.ReasonValidation, failindex.SourceWorkerValidation, err)
			return
		}
		span.SetAttributes(attribute.Int64("entire.installation_id", installationID))
		sreq = syncRequest{
			SourceKind:     gitjobs.SourceKindGithub,
			SourceOwner:    j.Source.Owner,
			SourceRepo:     j.Source.Repo,
			InstallationID: installationID,
			TargetULID:     j.Target.ULID,
		}
	case gitjobs.SourceKindEntireDB, gitjobs.SourceKindEntireDBNamespace:
		// Decode validation bounds the URL shape; admission here bounds where
		// the worker may present its client certificate. The environment-wide
		// domain is derived from Fleet's trusted local target configuration,
		// so sibling clusters are accepted without a per-cluster allowlist.
		sourceClusterParent, err := admitEntireDBSourceURL(j.Source.URL, c.sourceClusterDomain)
		if err != nil {
			err = permanentErr(fmt.Errorf("admit entiredb source: %w", err))
			span.RecordError(err)
			span.SetStatus(otelcodes.Error, "entiredb source outside allowed domain")
			span.SetAttributes(
				attribute.Bool("entire.error.permanent", true),
				attribute.Bool("entire.message.terminated", true),
			)
			slog.ErrorContext(ctx, "Entiredb source rejected, terminating", slog.Any("error", err))
			c.terminate(ctx, msg, parsed.SourceKind, j.Target.ULID, msg.Subject, msg.Data, failindex.ReasonValidation, failindex.SourceWorkerValidation, err)
			return
		}
		span.SetAttributes(attribute.String("entire.source_cluster_parent", sourceClusterParent))
		sreq = syncRequest{
			SourceKind:          parsed.SourceKind,
			SourceURL:           j.Source.URL,
			SourceClusterParent: sourceClusterParent,
			TargetULID:          j.Target.ULID,
		}
		// The namespace kind takes no snapshot: the per-repo ordinal it would
		// read is not namespace-scoped, so it is not evidence for a namespace
		// watermark. Its resync story is the scoped sweep (3b).
		if !sreq.namespaceScoped() {
			// Snapshot the source's write position BEFORE the fetch starts — the
			// ordering is what makes a ready completion's watermark claim sound.
			// Best-effort: a failed snapshot degrades to 0 and never blocks the
			// sync (ADR 20260818-native-mirror-resync-sweep).
			sourceState := c.snapshotSourcePosition(ctx, j.Source.URL, j.Target.ULID)
			sourcePosition = sourceState.Ordinal
			sreq.SourceRefsClaim = sourceState.Claim
			// The target assertion is only ever read on a source that came back
			// empty, so it is only asked for there — see assertTargetEmpty. Both
			// reads land before the fetch, which is the same ordering argument the
			// ordinal rests on: a claim about a repo's state is only worth
			// anything as of an instant that precedes the work it authorizes.
			if sreq.sourceAssertedEmpty() {
				sreq.TargetRefsClaim = c.targetRefsClaim(ctx, j.Target.ULID)
			}
			span.SetAttributes(
				attribute.Int64("entire.source_position", sourcePosition),
				attribute.Bool("entire.source_asserted_empty", sreq.sourceAssertedEmpty()),
				attribute.String("entire.source_refs_claim", sreq.SourceRefsClaim.String()),
				attribute.Bool("entire.target_asserted_empty", sreq.targetAssertedEmpty()),
				attribute.String("entire.target_refs_claim", sreq.TargetRefsClaim.String()),
			)
		}
	default:
		// UnmarshalFor already rejects unknown kinds, so this is defensive.
		err := permanentErr(fmt.Errorf("unsupported git source kind %q", parsed.SourceKind))
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "unsupported git source")
		span.SetAttributes(
			attribute.Bool("entire.error.permanent", true),
			attribute.Bool("entire.message.terminated", true),
		)
		slog.ErrorContext(ctx, "Unsupported git source, terminating", slog.String("source_kind", string(parsed.SourceKind)))
		c.terminate(ctx, msg, parsed.SourceKind, j.Target.ULID, msg.Subject, msg.Data, failindex.ReasonValidation, failindex.SourceWorkerValidation, err)
		return
	}

	// A single sync on a multi-GB repo regularly exceeds consumerAckWait, so
	// extend the ack deadline on a sub-AckWait cadence while sync runs. The
	// extender's lifetime is exactly the sync call: explicit stop right after
	// sync returns keeps it from overlapping with Ack/Term/Nak in
	// disposeResult (an InProgress racing an Ack would log a spurious warn),
	// and a deferred stop covers the panic path. stopExtender is idempotent,
	// so the two paths don't fight. We deliberately don't raise AckWait: if a
	// pod dies mid-job we still want redelivery within the configured window.
	stopExtender := startInProgressExtender(ctx, msg, consumerInProgressInterval)
	defer stopExtender()

	// Bound the attempt. git-sync is context-aware end to end (every HTTP
	// request is built with NewRequestWithContext), so the deadline aborts
	// in-flight transfers — which also stops the extender above, restoring
	// AckWait expiry as the backstop. A timeout classifies as transient →
	// Nak; a repo that exceeds the budget on every attempt exhausts
	// MaxDeliver and lands in the failure index (reason=max_deliveries).
	syncCtx := ctx
	if c.syncTimeout > 0 {
		var cancel context.CancelFunc
		syncCtx, cancel = context.WithTimeout(ctx, c.syncTimeout)
		defer cancel()
	}
	// Saturation + tail-latency instrumentation. syncStarted increments the
	// in-flight gauge and its deferred done() decrements it on every exit
	// (including a panic recovered upstream), keeping mirror.sync.active
	// balanced. elapsed is the wall-time around exactly the sync call; it is
	// threaded into disposeResult so mirror.sync.duration_seconds is tagged with
	// the real disposition (a slow ack vs a slow nak). Measured here, recorded
	// there, so the latency sample and the outcome label share one source.
	doneActive := c.metrics.syncStarted(ctx, c.jurisdiction)
	defer doneActive() // deferred so the decrement runs on every exit, including a sync panic recovered in handleMessage; otherwise the in-flight gauge leaks and biases utilization toward saturation
	start := time.Now()
	err := c.syncer.sync(syncCtx, sreq)
	elapsed := time.Since(start)
	stopExtender()
	if err != nil && errors.Is(syncCtx.Err(), context.DeadlineExceeded) && ctx.Err() == nil {
		// Our budget fired (not a process shutdown: the parent is still
		// alive). Wrap explicitly transient so the disposition can't be
		// swayed by however the aborted transfer's error happens to read,
		// and stamp the span so timed-out syncs are queryable.
		span.SetAttributes(attribute.Bool("entire.sync.deadline_exceeded", true))
		err = transientErr(fmt.Errorf("sync exceeded the %v budget: %w", c.syncTimeout, err))
	}

	// Tag concurrent-ref races so they stay queryable in traces even though
	// (below) they're deliberately not marked as span errors.
	if isConcurrentRefError(err) {
		span.SetAttributes(attribute.Bool("entire.sync.raced", true))
	}
	// Mark the span as an error only for genuine failures. Benign cases —
	// errSourceNoRefs (empty source, acked as a no-op) and a redelivering
	// concurrent-ref race — are excluded so they don't inflate the
	// mirror.consume APM error rate, matching their exclusion from the outcome
	// metric. See shouldMarkSpanError.
	if shouldMarkSpanError(err, isLastDelivery(msg)) {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "sync failed")
		span.SetAttributes(attribute.Bool("entire.error.permanent", isPermanentError(err)))
	}
	// A re-kicked job (cmd/rekicker) carries the Mirror-Rekick header; on success
	// the clear is tagged cleared{via=rekick} vs via=normal. Header.Get only
	// exists on *nats.Msg, not the ackableMsg disposition seam, so read it here
	// and thread the flag down rather than widen the interface.
	viaRekick := msg.Header.Get(failindex.RekickHeader) != ""
	c.disposeResult(ctx, msg, err, parsed.SourceKind, j.Target.ULID, msg.Subject, msg.Data, viaRekick, elapsed, sourcePosition)
}

// disposeResult applies the JetStream action for a sync result and records the
// outcome metrics. elapsed is the wall-time of the sync attempt (measured in
// handleGitJob); it is recorded on mirror.sync.duration_seconds tagged with the
// disposition resolved here, so the latency sample carries the real outcome.
func (c *consumer) disposeResult(ctx context.Context, m ackableMsg, err error, kind gitjobs.SourceKind, ulid, subject string, payload []byte, viaRekick bool, elapsed time.Duration, sourcePosition int64) {
	provider := string(kind)
	seq := streamSeq(m)
	switch classifyDisposition(err) {
	case dispositionAck:
		// A ref-applying sync — or a source and target both confirmed empty,
		// which applies nothing but proves the placement matches, so it
		// carries a position like any other success (see dispositionNoop for
		// the cases that deliberately do not).
		//
		// Publish the ready completion BEFORE acking. entire-core flips
		// mirror_repos.status (processing → ready) off this event, and once we
		// ack the job leaves the work-queue stream and is never redelivered — so
		// a publish lost after the ack would strand the row in 'processing'
		// forever, hanging the CLI's status poll. publishReadyOrRetry holds the
		// ack until the publish lands (or preserves the job for recovery); see
		// its doc for the at-least-once rationale.
		if !c.publishReadyOrRetry(ctx, m, kind, ulid, subject, payload, elapsed, sourcePosition, false) {
			return
		}
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeAck, elapsed)
		_ = m.Ack()
		c.clearIndex(ctx, kind, ulid, seq, viaRekick) // repo healed → drop any stale index entry
	case dispositionNoop:
		// No refs to apply, but the mirror IS clonable (an empty repo is a
		// valid clone target), so it's 'ready' to entire-core. Same
		// publish-before-ack discipline as the success path. A noop must retain
		// sync failures because it reconciled no refs. Once ready publication
		// succeeds, it may clear a completion-only failure, guarded by source,
		// stream sequence and KV revision. Other failures remain until a real
		// sync or explicit operator resolution; unresolved entries never expire.
		//
		// For the same reason the completion carries NO source position: a
		// noop applied nothing, so the pre-fetch snapshot is NOT evidence that
		// the placement covers that position — stamping it would over-advance
		// the applied watermark and hide the stale placement from the resync
		// sweep forever (a source whose refs were all deleted no-ops here
		// while the target still serves them). Position 0 = "no watermark
		// evidence"; the sweep stays responsible for the divergence.
		//
		// The one ref-less case that IS proven coverage does not arrive here:
		// a source git-sync confirmed empty whose target is empty too has
		// nothing to diverge, so it returns success and takes the Ack path
		// above WITH its position (see classifyEmptySource / Converged).
		// That is the difference between "we applied nothing" and "there is
		// nothing to apply and we checked both sides".
		if !c.publishReadyOrRetry(ctx, m, kind, ulid, subject, payload, elapsed, 0, true) {
			return
		}
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeNoop, elapsed)
		_ = m.Ack()
		if c.donePub != nil {
			c.clearFailureIndex(ctx, kind, ulid, seq, viaRekick, true)
		}
	case dispositionTerm:
		// Best-effort record, then Term regardless — fail open. recordTerminal
		// logs + counts record_failed{cause} on a KV write failure; we Term
		// either way rather than Nak, because the failure is permanent (re-running
		// the sync would be wasted work) and a KV outage must not wedge the
		// consumer. Recovery of a dropped record is owned by the record_failed
		// alert + L2 reconcile, not by holding the message.
		c.recordTerminal(ctx, kind, ulid, subject, payload, seq, failindex.ReasonPermanent, failindex.SourceWorkerPermanent, err)
		slog.WarnContext(ctx, "Permanent sync error, terminating", slog.Any("error", err))
		c.publishFailed(ctx, kind, ulid) // best-effort: tell entire-core the clone won't land
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeTerm, elapsed)
		_ = m.Term()
	case dispositionNak:
		if isLastDelivery(m) {
			// Final delivery: JetStream won't redeliver past consumerMaxDeliver,
			// so this is terminal. Best-effort record (max_deliveries), then Term —
			// fail open (recordTerminal surfaces a write failure via record_failed).
			c.recordTerminal(ctx, kind, ulid, subject, payload, seq, failindex.ReasonMaxDeliveries, failindex.SourceWorkerExhausted, err)
			slog.ErrorContext(ctx, "Sync failed; deliveries exhausted, terminating", slog.Any("error", err))
			c.publishFailed(ctx, kind, ulid) // best-effort: clone exhausted retries, won't land
			c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeTerm, elapsed)
			_ = m.Term()
			return
		}
		slog.ErrorContext(ctx, "Sync failed", slog.Any("error", err))
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeNak, elapsed)
		_ = m.NakWithDelay(consumerFailureDelay)
	case dispositionRaced:
		// Target ref moved between this job's plan and its push — a second sync
		// of the same repo won the race (rapid webhooks, or a webhook
		// overlapping the rekicker). Redeliver like a nak so the next delivery
		// re-plans against the new tip and applies cleanly (usually a no-op,
		// since the winner already mirrored the same source state), but record
		// outcomeRaced + WARN so it stays out of the sync-failure alert's
		// nak+term numerator: it self-heals and pages no one.
		//
		// Final-delivery escalation is identical to the nak path for the failure
		// index + alert: if a repo somehow races every delivery to exhaustion the
		// contention is no longer benign, so we record terminal (max_deliveries)
		// and label outcome=term — that DOES reach the alert. Fail open on the
		// index write exactly like dispositionNak.
		//
		// But we deliberately do NOT publish a 'failed' completion here. A raced
		// error (ErrTargetRefMoved) means the target ref moved under us — i.e. a
		// CONCURRENT sync of the same ULID is racing us, and one of those is the
		// likely winner that publishes 'ready'. Emitting 'failed' would describe
		// contention as an unclonable mirror; entire-core's MarkReady would heal
		// it on the winner's event anyway, but skipping 'failed' avoids the
		// misleading transient flip entirely. If no sibling ever wins (pathological
		// — they can't all lose), status lingers at 'processing' and the failure
		// index/alert still fire.
		if isLastDelivery(m) {
			c.recordTerminal(ctx, kind, ulid, subject, payload, seq, failindex.ReasonMaxDeliveries, failindex.SourceWorkerExhausted, err)
			slog.ErrorContext(ctx, "Sync kept racing on target ref; deliveries exhausted, terminating", slog.Any("error", err))
			c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeTerm, elapsed)
			_ = m.Term()
			return
		}
		slog.WarnContext(ctx, "Sync raced on target ref; will retry", slog.Any("error", err))
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeRaced, elapsed)
		_ = m.NakWithDelay(consumerFailureDelay)
	}
}

// publishReadyOrRetry publishes the StatusReady completion and reports whether
// the caller may proceed to Ack. It returns true when the publish lands (or
// when no publisher is wired, or there's no ULID to key on) — the ack is safe.
//
// On a publish failure it does NOT ack: the completion is the only signal
// entire-core gets that the clone finished, and acking would drop it for good.
// Instead it Naks so JetStream redelivers before the final delivery. The
// next attempt re-runs the idempotent sync (a near-noop — refs already
// applied), and re-publishes. On the final delivery, retain the original
// message and capture the incomplete completion in the failure index for a
// re-kick. Never Ack or Term: even if KV is unavailable, the exhausted job
// remains inspectable/recoverable until stream retention expires. A successful
// sync is not a failed mirror: do not publish StatusFailed for this case.
func (c *consumer) publishReadyOrRetry(ctx context.Context, m ackableMsg, kind gitjobs.SourceKind, ulid, subject string, payload []byte, elapsed time.Duration, sourcePosition int64, noop bool) (proceed bool) {
	if c.donePub == nil || ulid == "" {
		return true
	}
	err := c.donePub.PublishCompletion(ctx, c.jurisdiction, c.clusterID, donejobs.Job{
		RepoULID:       ulid,
		Status:         donejobs.StatusReady,
		SourcePosition: sourcePosition,
		SourceKind:     string(kind),
	})
	if err == nil {
		c.metrics.recordDonePublished(ctx, string(donejobs.StatusReady), true)
		return true
	}
	c.metrics.recordDonePublished(ctx, string(donejobs.StatusReady), false)
	if isLastDelivery(m) {
		c.recordFailure(ctx, kind, ulid, subject, payload, streamSeq(m), failindex.ReasonMaxDeliveries, failindex.SourceWorkerCompletion, fmt.Errorf("sync succeeded but ready completion failed: %w", err), noop)
		slog.ErrorContext(ctx, "Ready completion failed on final delivery; retaining job for recovery", slog.String("target_ulid", ulid), slog.Any("error", err))
	}

	slog.ErrorContext(ctx, "Failed to publish mirror completion; naking to retry", slog.String("target_ulid", ulid), slog.Any("error", err))
	c.metrics.recordSyncOutcome(ctx, string(kind), c.jurisdiction, outcomeNak, elapsed)
	_ = m.NakWithDelay(consumerFailureDelay)
	return false
}

// publishFailed publishes the StatusFailed completion on a best-effort basis:
// any error is logged and counted, never escalated. The message is already
// being Term'd (a permanent or retry-exhausted failure), so re-running the
// doomed sync to retry the publish would be wasted work; a lost 'failed' just
// leaves entire-core's row in 'processing' until the CLI's poll times out
// client-side — degraded, not incorrect. Mirrors the fail-open discipline
// recordTerminal already uses for the KV index.
func (c *consumer) publishFailed(ctx context.Context, kind gitjobs.SourceKind, ulid string) {
	if c.donePub == nil || ulid == "" {
		return
	}
	err := c.donePub.PublishCompletion(ctx, c.jurisdiction, c.clusterID, donejobs.Job{
		RepoULID:   ulid,
		Status:     donejobs.StatusFailed,
		SourceKind: string(kind),
	})
	if err != nil {
		slog.ErrorContext(ctx, "Failed to publish mirror failed-completion (best-effort, terminating anyway)",
			slog.String("target_ulid", ulid), slog.Any("error", err))
		c.metrics.recordDonePublished(ctx, string(donejobs.StatusFailed), false)
		return
	}
	c.metrics.recordDonePublished(ctx, string(donejobs.StatusFailed), true)
}

// disposition is the JetStream action disposeResult takes for a sync result.
type disposition int

const (
	dispositionAck   disposition = iota // success → Ack
	dispositionNoop                     // benign empty-source no-op → Ack
	dispositionTerm                     // permanent failure → Term (no redelivery)
	dispositionNak                      // transient failure → Nak (redeliver)
	dispositionRaced                    // benign concurrent-ref miss → Nak (redeliver), but counted as outcomeRaced not outcomeNak
)

// classifyDisposition maps a sync() result to its JetStream disposition. Pure
// (no IO) so the ack/noop/term/nak decision is unit-testable independent of a
// live subscription; disposeResult owns the side effects.
func classifyDisposition(err error) disposition {
	switch {
	case err == nil:
		return dispositionAck
	case errors.Is(err, errSourceNoRefs):
		return dispositionNoop
	case isPermanentError(err):
		return dispositionTerm
	case isConcurrentRefError(err):
		// Checked after isPermanentError so a 4xx that happens to echo a
		// concurrent-ref phrase still terminates; concurrent-ref errors are
		// never marked permanent, so this only ever reclassifies the transient
		// (would-be-nak) tail.
		return dispositionRaced
	default:
		return dispositionNak
	}
}

func isPermanentError(err error) bool {
	var se *syncError
	if errors.As(err, &se) {
		return se.permanent
	}
	return false
}

// streamSeq returns the message's JetStream stream sequence, or 0 if metadata
// is unavailable (e.g. a synthetic test message). Used as the failure-index
// dedup token and the clear-on-success ordering guard.
func streamSeq(msg ackableMsg) uint64 {
	if meta, err := msg.Metadata(); err == nil {
		return meta.Sequence.Stream
	}
	return 0
}

// isLastDelivery reports whether this is the final delivery before JetStream
// stops redelivering (NumDelivered has reached consumerMaxDeliver).
func isLastDelivery(msg ackableMsg) bool {
	if meta, err := msg.Metadata(); err == nil {
		return meta.NumDelivered >= consumerMaxDeliver
	}
	return false
}

// recordTerminal makes a BEST-EFFORT write of a terminal failure to the KV
// index. It never gates the caller's disposal: on a KV write failure it fails
// open — logs and increments record_failed{cause}. Completion publication
// failure retains the original message; the other terminal callers Term the
// message anyway rather than Nak-ing. A KV outage must not wedge the consumer or
// burn re-sync retries (the record-failure paths are permanent/validation/
// exhausted, where a re-sync is wasted or moot). Recovery of a dropped record is
// owned by the record_failed alert and the L2 reconcile, not by holding the
// message.
func (c *consumer) recordTerminal(ctx context.Context, kind gitjobs.SourceKind, ulid, subject string, payload []byte, seq uint64, reason failindex.FailureReason, source string, cause error) {
	c.recordFailure(ctx, kind, ulid, subject, payload, seq, reason, source, cause, false)
}

func (c *consumer) recordFailure(ctx context.Context, kind gitjobs.SourceKind, ulid, subject string, payload []byte, seq uint64, reason failindex.FailureReason, source string, cause error, noopCompletion bool) {
	if skipsFailureIndex(kind) {
		return
	}
	if c.failidx == nil {
		// Index unbound — cannot capture this failure. Surface it because
		// depth/recorded stay flat otherwise. The caller owns disposition.
		c.metrics.recordIndexUnavailable(ctx, failedIndexCauseUnbound)
		return
	}
	if ulid == "" {
		// Reachable: a payload that fails json decoding entirely carries no
		// target ULID to key a record on. Nothing to capture.
		return
	}
	fs := failindex.FailedSync{
		Subject:   subject,
		Payload:   payload,
		Reason:    reason,
		Source:    source,
		LastError: truncateError(cause),
	}
	record := c.failidx.RecordFailure
	if noopCompletion {
		record = c.failidx.RecordNoopCompletionFailure
	}
	recorded, err := record(ulid, fs, seq, time.Now())
	if err != nil {
		// Log and count the failure; the caller owns message disposition.
		slog.ErrorContext(ctx, "Failed to record failure to index",
			slog.String("target_ulid", ulid), slog.String("reason", string(reason)), slog.Any("error", err))
		c.metrics.recordIndexUnavailable(ctx, failedIndexCauseWriteError)
		return
	}
	// Only count a genuine record — a dedup/reorder no-op (recorded=false) means
	// the failure was already captured, so counting it would inflate recorded
	// on a redelivery or the in-process/advisory pair.
	if recorded {
		c.metrics.recordIndexed(ctx, string(reason))
	}
}

// terminate records a terminal failure (best-effort) then Terms. Used by the
// pre-sync validation rejects, which carry no sync-outcome metric. These are
// permanent failures of a well-formed job (unsupported op/source kind, bad
// auth ref) — the clone will never land — so publish 'failed' best-effort so
// entire-core flips mirror_repos.status off 'processing' rather than the CLI
// poll hanging until timeout.
func (c *consumer) terminate(ctx context.Context, m ackableMsg, kind gitjobs.SourceKind, ulid, subject string, payload []byte, reason failindex.FailureReason, source string, cause error) {
	c.recordTerminal(ctx, kind, ulid, subject, payload, streamSeq(m), reason, source, cause)
	c.publishFailed(ctx, kind, ulid)
	_ = m.Term()
}

// clearIndex removes the repo's failure-index entry after a successful sync.
// Best-effort: a failure here is logged but never fails the sync (it already
// succeeded; a stale entry self-heals on the next success or re-kick). viaRekick
// tags the cleared metric so an operator can tell re-kicker-driven recoveries
// (cleared{via=rekick}) from organic ones (via=normal) — the "are re-kicks
// healing repos?" signal.
func (c *consumer) clearIndex(ctx context.Context, kind gitjobs.SourceKind, ulid string, seq uint64, viaRekick bool) {
	c.clearFailureIndex(ctx, kind, ulid, seq, viaRekick, false)
}

func (c *consumer) clearFailureIndex(ctx context.Context, kind gitjobs.SourceKind, ulid string, seq uint64, viaRekick, completionOnly bool) {
	if skipsFailureIndex(kind) {
		return
	}
	if c.failidx == nil || ulid == "" {
		return
	}
	clear := c.failidx.ClearOnSuccess
	if completionOnly {
		clear = c.failidx.ClearOnCompletion
	}
	cleared, err := clear(ulid, seq)
	if err != nil {
		slog.WarnContext(ctx, "Failed to clear failure index after success",
			slog.String("target_ulid", ulid), slog.Any("error", err))
		return
	}
	if cleared {
		via := clearedViaNormal
		if viaRekick {
			via = clearedViaRekick
		}
		c.metrics.recordCleared(ctx, via)
	}
}

// skipsFailureIndex reports whether a kind stays out of the failure index. The
// index is keyed by target ULID alone, so a namespace entry would overwrite the
// GitHub failure for the same placement and a namespace success would clear it;
// the namespace kind's retry story is the scoped sweep (3b), not the rekicker.
func skipsFailureIndex(kind gitjobs.SourceKind) bool {
	return kind == gitjobs.SourceKindEntireDBNamespace
}

// truncateError renders an error for the index, capped so a pathological message
// can't bloat the KV value.
func truncateError(err error) string {
	if err == nil {
		return ""
	}
	const max = 1024
	s := err.Error()
	if len(s) > max {
		return s[:max]
	}
	return s
}

// inProgressMsg is the subset of *nats.Msg used by the in-progress extender.
// A tiny interface seam so the loop is unit-testable without a live JetStream
// subscription. Signature mirrors *nats.Msg.InProgress (variadic AckOpt) so
// the concrete type satisfies the interface implicitly.
type inProgressMsg interface {
	InProgress(opts ...nats.AckOpt) error
}

// startInProgressExtender periodically calls msg.InProgress() to push back the
// JetStream redelivery deadline while a long-running operation (a git sync)
// is still in flight. Returns a stop function that cancels the loop and blocks
// until the goroutine has exited — so a defer-stop won't leak the goroutine.
//
// InProgress() errors are logged and swallowed: a transient extend failure
// shouldn't kill an otherwise healthy job. Worst case the sync exceeds
// AckWait without a successful extend and JetStream redelivers — the same
// redelivery path that already exists today.
func startInProgressExtender(ctx context.Context, msg inProgressMsg, interval time.Duration) (stop func()) {
	ctx, cancel := context.WithCancel(ctx)
	done := make(chan struct{})
	go func() {
		defer close(done)
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				if err := msg.InProgress(); err != nil {
					slog.WarnContext(ctx, "InProgress extend failed", slog.Any("error", err))
				}
			}
		}
	}()
	return func() {
		cancel()
		<-done
	}
}

package main

import (
	"context"
	"fmt"
	"log/slog"
	"net/http"
	"net/url"
	"time"

	"entire.io/entire/git-sync"
	"go.opentelemetry.io/contrib/instrumentation/net/http/otelhttp"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/pkg/gitjobs"
)

// maxSyncAttempts bounds in-process retries for transient git-fetch failures.
// Production measurement over 14 days of @entire.sync.attempts on mirror.sync
// spans showed attempt 1 = 147,132 syncs, attempt 2 = 3,573 (2.4% of attempt 1
// continued), attempt 3 = 862 (24% of attempt 2 continued) — under the old
// 3-attempt budget, that attempt-3 tail left ~1.2 terminal 404s/day. The two
// continuation rates differ by an order of magnitude, so the decay beyond
// attempt 3 isn't known and a precise residual-failure estimate at 8 attempts
// isn't supported by this data; widening the budget is expected to clear
// materially more of the attempt-3 tail without a confident number attached.
const maxSyncAttempts = 8

// syncRetryDelay paces in-process retries. The shortest observed gap between
// a 404 and a successful sibling sync of the same repo was ~3s, so a 2s
// delay sits just under that boundary — long enough for GitHub's git edge
// to settle after a mint, short enough to stay responsive. Kept fixed (no
// exponential backoff): the continuation rates behind maxSyncAttempts were
// measured at this exact spacing, so changing it would invalidate that data.
const syncRetryDelay = 2 * time.Second

// unmirroredRefPrefix marks branches that live only in Entire and are never
// mirrored to/from GitHub. Excluding it from the sync scope also excludes it
// from prune, so a GitHub→Entire sync can't delete an unmirrored branch that
// (by definition) has no counterpart on the source. This is the inbound half
// of the contract; the outbound half (skipping push-through) lives in
// entiredb's server/githttp. entiredb pins the same literal as
// mirror.UnmirroredRefPrefix — kept in lockstep here because the two live in
// separate Go modules. See entiredb docs/adrs/20260702-unmirrored-branches.md.
const unmirroredRefPrefix = "refs/heads/entire/unmirrored/"

// namespaceRefPrefix is the Entire-owned ref namespace (COR-1563). entiredb's
// writer scope refuses a push to it that does not declare the namespace sync
// kind, so a GitHub-kind sync — AllRefs + prune — must exclude it, or it plans
// a delete of every namespace ref the target holds and fails on every
// redelivery. entiredb pins the same literal as forge.NativeRefPrefix; kept in
// lockstep here because the two live in separate Go modules.
const namespaceRefPrefix = "refs/heads/entire/native/"

// reservedAncestorRefs are the bare directory-anchor refs entiredb blocks from
// creation so the namespace beneath each stays usable: a leaf ref squatting an
// anchor would directory/file-conflict with every ref under it. entiredb
// rejects a push to any of them, so the worker must skip them on inbound sync
// or a source repo that happens to carry one would fail the whole mirror.
// These are exact-match (ExcludeRefs), NOT prefixes, so a normal ref like
// refs/heads/entire/a or refs/meta/entire/main still passes this filter.
//
// The refs/heads/* pair protects the unmirrored-branches feature (entiredb
// docs/adrs/20260702-unmirrored-branches.md); the refs/meta pair are base
// anchors entiredb reserves for EVERY caller — a workload carve-out matches by
// prefix + "/" and so never reaches the bare anchor. Keep in lockstep with the
// reservedExact set in entiredb's refpolicy/refpolicy.go.
var reservedAncestorRefs = []string{
	"refs/heads/entire",
	"refs/heads/entire/unmirrored",
	"refs/meta",
	"refs/meta/entire",
}

// excludeRefPrefixes are the source ref namespaces the worker never mirrors
// (and, being unmirrored, never prunes) on a GITHUB sync. Shared between the
// sync scope and the default-branch reconcile guard: a source HEAD under one
// of these prefixes can never land on the target, so the reconcile treats it
// as non-convergent rather than looping forever (see isNonMirrorableBranch —
// which deliberately keeps checking THIS list for both kinds, because
// entiredb's SetDefaultBranch rejects an unmirrored-namespace default
// unconditionally). The refs/heads/ entries here are the only ones a HEAD
// could point at; the rest are kept for a single source of truth with the
// sync scope. entiredb-kind syncs use excludeRefPrefixesFor, which drops
// exactly one entry.
var excludeRefPrefixes = []string{
	"refs/pull/",
	"refs/heads/trunk-merge/",
	"refs/heads/gh-readonly-queue/",
	"refs/tlog/",
	"refs/remotes/",
	"refs/internal/",
	"refs/replace/",
	"refs/bisect/",

	// Only Entire's own managed sub-namespace is reserved, NOT all of
	// refs/meta/. entiredb reserves refs/meta/entire/* (refpolicy's
	// ManagedMetaPrefix) and carves it out for the entire-api workload alone,
	// which the worker is not — so the worker must still skip it. The rest of
	// refs/meta/* is unreserved by design: standard git-meta clients push
	// refs/meta/config and friends directly, and those mirror like any other
	// ref. See entiredb refpolicy/refpolicy.go and its ADR
	// docs/adrs/20260603-reserved-refs.md.
	"refs/meta/entire/",

	"refs/namespaces/",
	"refs/stash", // covers the exact refs/stash ref and refs/stash/*

	// refs/heads/entire/unmirrored/* are Entire-only branches (see
	// unmirroredRefPrefix). Excluded so Prune never deletes one for being
	// absent on GitHub; the outbound push-through skip that keeps them off
	// GitHub lives in entiredb.
	unmirroredRefPrefix,
}

// githubExcludeRefPrefixes is the GitHub-kind scope: excludeRefPrefixes plus
// the Entire-owned namespace. Kept OUT of excludeRefPrefixes itself because
// that list also backs the kind-blind isNonMirrorableBranch, and entiredb
// reserves the namespace on GitHub-mirror rows only — a native mirror may
// carry a namespace branch as its default and its HEAD must follow it. A
// GitHub HEAD there needs no local guard: entiredb answers SetDefaultBranch
// with InvalidArgument, which recoveryIsPermanent already terminates on.
var githubExcludeRefPrefixes = append(append([]string(nil), excludeRefPrefixes...), namespaceRefPrefix)

// namespaceRefAnchor is the bare directory anchor of the Entire-owned
// namespace. It is not covered by namespaceRefPrefix (no trailing slash) and
// entiredb's writer scope refuses it on a GitHub-mirror row exactly like the
// refs beneath it, so both kinds that touch such a row must exclude it
// exactly — as a prefix it would also swallow refs/heads/entire/nativeish.
const namespaceRefAnchor = "refs/heads/entire/native"

// excludeRefsWithAnchor is reservedAncestorRefs plus the namespace anchor, for
// the two kinds that write a GitHub-mirror row.
var excludeRefsWithAnchor = append(append([]string(nil), reservedAncestorRefs...), namespaceRefAnchor)

// includeRefPrefixesFor returns the namespaces a kind may manage, or nil for
// the unnarrowed kinds. It is the whole defence for a namespace sync: git-sync
// neither pushes nor prunes a ref outside the returned set.
func includeRefPrefixesFor(kind gitjobs.SourceKind) []string {
	if kind == gitjobs.SourceKindEntireDBNamespace {
		return []string{namespaceRefPrefix}
	}
	return nil
}

// excludeRefsFor returns the exact-match sync-scope exclusions for a kind. Only
// the entiredb kind keeps the bare list: on a native row the anchor is an
// ordinary branch name entiredb reserves nothing beneath.
func excludeRefsFor(kind gitjobs.SourceKind) []string {
	if kind == gitjobs.SourceKindEntireDB {
		return reservedAncestorRefs
	}
	return excludeRefsWithAnchor
}

// excludeRefPrefixesFor returns the sync-scope exclusions for a source kind.
// A GitHub-kind sync additionally excludes the Entire-owned namespace (see
// githubExcludeRefPrefixes). An entiredb-kind sync (native mirroring) drops
// exactly the unmirrored-namespace exclusion and nothing else (plan decision
// 3, ADR 20260720-native-mirroring): that exclusion exists to keep Entire-only
// branches out of a GitHub round-trip, and when the source IS entiredb the
// namespace replicates like any branch — a native mirror is a full read-only
// copy. Everything else stays excluded for the same reasons as GitHub:
// refs/tlog/* is per-placement entiredb-owned state receive-pack rejects,
// and the reserved namespaces would 403 the push.
func excludeRefPrefixesFor(kind gitjobs.SourceKind) []string {
	if kind == gitjobs.SourceKindEntireDBNamespace {
		// Scoped by inclusion, not exclusion: every ref outside the namespace is
		// already out of scope, including git-sync's own bootstrap markers,
		// which take their scope from the branch they checkpoint.
		return nil
	}
	if kind != gitjobs.SourceKindEntireDB {
		return githubExcludeRefPrefixes
	}
	out := make([]string, 0, len(excludeRefPrefixes)-1)
	for _, p := range excludeRefPrefixes {
		if p != unmirroredRefPrefix {
			out = append(out, p)
		}
	}
	return out
}

// tokenMinter mints a GitHub App installation token for a given mirror job.
// The full mirror coordinates (target repo ULID + source owner/repo +
// installation ID) are passed through so the entire-core STS mint endpoint
// can authorize against its stored mirror metadata. Kept as an interface so
// tests can inject a known-token fake to verify log redaction.
type tokenMinter interface {
	InstallationToken(ctx context.Context, targetRepo, owner, repo string, installationID int64) (string, error)
}

type syncer struct {
	bootstrapFallbackMaxPackBytes int64
	httpClient                    *http.Client
	sourceBaseURL                 string
	targetBaseURL                 string
	// targetClusters, publicBase, and clusterBase are the ingredients of
	// httpClient's clusterTransport, kept so httpClientFor can mint a
	// per-sync variant whose cluster set additionally trusts an
	// entiredb-kind job's source cluster.
	targetClusters []string
	publicBase     http.RoundTripper
	clusterBase    http.RoundTripper
	// replicas is the shared repo → hosting-replica-set cache behind every
	// clusterTransport this syncer mints (see replicaCache). One per
	// syncer so a set learned on one sync serves the next. entryHosts is
	// the target entry host:port the cache is keyed and consulted on;
	// httpClientFor prepends an entiredb source's per sync.
	replicas   *replicaCache
	entryHosts []string
	githubApp  tokenMinter
	// metrics records the source-auth mint duration. nil-safe (the recorder
	// guards nil) so syncer tests that don't wire metrics still mint.
	metrics *workerMetrics
	// repoAdmin is entiredb's RepoAdmin.SetDefaultBranch client, riding the
	// same cluster mTLS credential as the git push (cert-only, no bearer).
	// Nil when the svctok internal URL isn't configured (dev/loadtest) —
	// the default-branch reconcile is then disabled and a source rename
	// keeps failing the sync exactly as before.
	repoAdmin defaultBranchSetter
}

type syncRequest struct {
	// SourceKind selects the source leg: github (owner/repo against
	// sourceBaseURL, App-token auth) or entiredb (SourceURL, cert-only).
	// The zero value means github so existing callers/tests read unchanged.
	SourceKind     gitjobs.SourceKind
	SourceOwner    string
	SourceRepo     string
	InstallationID int64
	// SourceURL is the by-ID git URL of the source repo on its home entiredb
	// cluster. SourceClusterParent is the consume-time admitted transport
	// boundary; the syncer must not derive certificate routing from SourceURL.
	// Both are entiredb-kind only.
	SourceURL           string
	SourceClusterParent string
	TargetULID          string
	// SourceRefsClaim and TargetRefsClaim carry the entiredb data plane's
	// authoritative refs answer for each leg, read from
	// RepoAdmin.GetWritePosition before the fetch (see
	// consumer.snapshotSourcePosition / targetRefsClaim). They are the
	// inputs git-sync cannot derive for itself — ref hiding makes an empty
	// advertisement and a populated repository the same observation, on each
	// leg independently. Only the emptiness claim reaches git-sync (as
	// SyncPolicy.SourceAssertedEmpty / TargetAssertedEmpty); both legs keep
	// the full tri-state because classifyEmptySource needs it to separate "no
	// answer arrived" from "the repo's own records say it holds refs" —
	// no-op outcomes with opposite remedies (see emptyReasonWithheld /
	// emptyReasonTargetWithheld).
	//
	// Both default to withholding the claim (refsClaimNone). Every failure to
	// read one lands there, so an unreadable server costs a convergence
	// rather than fabricating one. entiredb-kind only: nothing answers this
	// question for a GitHub source, and nothing there would use the answer.
	SourceRefsClaim refsClaim
	TargetRefsClaim refsClaim
}

// sourceAssertedEmpty / targetAssertedEmpty report whether the leg's entiredb
// data plane explicitly claimed the repo holds no refs — the only claim state
// git-sync consumes.
func (r syncRequest) sourceAssertedEmpty() bool { return r.SourceRefsClaim == refsClaimEmpty }
func (r syncRequest) targetAssertedEmpty() bool { return r.TargetRefsClaim == refsClaimEmpty }

type syncerConfig struct {
	bootstrapFallbackMaxPackBytes int64
	sourceBaseURL                 string
	targetBaseURL                 string
	// targetClusterHost overrides the in-cluster transport matcher. Empty
	// means derive from targetBaseURL (single-URL flows). When
	// ENTIRE_TARGET_INTERNAL_URL is set, main.go strips the svctok
	// prefix to produce a parent host that matches both the svctok
	// endpoint and the per-node hosts entiredb 307s to — without this,
	// the receive-pack POST after a /info/refs cross-host redirect
	// falls off the mTLS transport and is rejected at the handshake.
	targetClusterHost string
	githubApp         tokenMinter
	// targetTransport is the in-cluster round-tripper for push traffic to
	// the target cluster. Nil = use http.DefaultTransport (dev/loadtest,
	// single-URL dial). Set to the mTLS reloader when targetBaseURL points
	// at the cluster's svctok :8281 endpoint: the client cert is the whole
	// credential there — entiredb authorizes the worker cert-only from its
	// inbound write-mirror allowlist (COR-536), no bearer attached.
	targetTransport http.RoundTripper
	// metrics records the source-auth mint duration (mirror.source_auth.
	// duration_seconds). nil-safe.
	metrics *workerMetrics
	// repoAdmin enables the default-branch reconcile when non-nil. See
	// syncer.repoAdmin.
	repoAdmin defaultBranchSetter
}

func newSyncer(cfg syncerConfig) (*syncer, error) {
	// The cluster trust boundary is either explicitly configured
	// (cfg.targetClusterHost — set from resolveTargetClusterHost when
	// ENTIRE_TARGET_INTERNAL_URL diverges from the audience URL) or
	// derived from targetBaseURL. When ENTIRE_TARGET_URL points at the
	// cluster entry domain (royalcanin.partial.to), the host is the
	// FQDN itself and nodeN.royalcanin.partial.to matches as a subdomain
	// — so the info/refs 307 redirect carries auth headers through.
	// Pointing at a specific node (node1.royalcanin.partial.to) narrows
	// the trust boundary to that one node — info/refs 307s to sibling
	// nodes will lose auth, which is acceptable for debug/rollback but
	// not for steady-state operation.
	clusterHost := cfg.targetClusterHost
	if clusterHost == "" {
		derived, err := targetBaseURLHost(cfg.targetBaseURL)
		if err != nil {
			return nil, err
		}
		clusterHost = derived
	}

	// GitHub source fetches MUST ride a public-CA transport — the internal
	// mTLS transport's RootCAs only trust the cluster CA and would fail
	// x509 verification on github.com. Target pushes — and, per sync,
	// entiredb source fetches (see httpClientFor) — ride
	// cfg.targetTransport (svctok mTLS) when configured. Split so the two
	// paths can't conflict; clusterTransport routes by destination host.
	sourceBase := otelhttp.NewTransport(
		http.DefaultTransport,
		otelhttp.WithSpanNameFormatter(gitSmartHTTPSpanName),
	)
	var clusterBase http.RoundTripper
	if cfg.targetTransport != nil {
		clusterBase = otelhttp.NewTransport(
			cfg.targetTransport,
			otelhttp.WithSpanNameFormatter(gitSmartHTTPSpanName),
		)
	}
	targetClusters := []string{clusterHost}
	targetEntryHost, err := entryHostPort(cfg.targetBaseURL)
	if err != nil {
		return nil, err
	}
	entryHosts := []string{targetEntryHost}
	replicas := newReplicaCache()
	transport := &clusterTransport{
		clusters:    targetClusters,
		entryHosts:  entryHosts,
		base:        sourceBase,
		clusterBase: clusterBase,
		replicas:    replicas,
		metrics:     cfg.metrics,
	}

	return &syncer{
		bootstrapFallbackMaxPackBytes: cfg.bootstrapFallbackMaxPackBytes,
		httpClient:                    &http.Client{Transport: transport},
		sourceBaseURL:                 cfg.sourceBaseURL,
		targetBaseURL:                 cfg.targetBaseURL,
		targetClusters:                targetClusters,
		publicBase:                    sourceBase,
		clusterBase:                   clusterBase,
		replicas:                      replicas,
		entryHosts:                    entryHosts,
		githubApp:                     cfg.githubApp,
		metrics:                       cfg.metrics,
		repoAdmin:                     cfg.repoAdmin,
	}, nil
}

// httpClientFor returns the HTTP client for one sync. github-kind syncs
// share the long-lived client (target rides mTLS, github.com rides the
// public-CA base). An entiredb-kind sync gets a per-sync client whose
// cluster set additionally trusts the consume-time admitted source cluster
// parent — so the fetch, and the per-node hosts the source cluster's
// /info/refs 307s to, present the client cert (the whole credential: the
// source's svctok listener grants the workload cert-only cluster-wide pull).
// The raw SourceURL never expands this trust set. With no mTLS transport
// configured (dev/loadtest single-URL setups) the per-sync client degrades to
// the shared public base exactly like target pushes do.
func (s *syncer) httpClientFor(req syncRequest) *http.Client {
	if !req.entiredbSourced() {
		return s.httpClient
	}
	clusters := append([]string{req.SourceClusterParent}, s.targetClusters...)
	// The source's svctok host is an entry host for this sync: its
	// /info/refs 307s off non-hosting nodes exactly like the target's, and
	// its replica set is cached under its own key. Admission has already
	// validated SourceURL's shape, so a parse failure here just leaves the
	// source uncached rather than failing the sync.
	entryHosts := s.entryHosts
	if h, err := entryHostPort(req.SourceURL); err == nil {
		entryHosts = append([]string{h}, s.entryHosts...)
	}
	var rt http.RoundTripper = &clusterTransport{
		clusters:    clusters,
		entryHosts:  entryHosts,
		base:        s.publicBase,
		clusterBase: s.clusterBase,
		replicas:    s.replicas,
		metrics:     s.metrics,
	}
	if req.namespaceScoped() {
		rt = &syncKindTransport{base: rt, kind: syncKindNamespace, clusters: s.targetClusters}
	}
	return &http.Client{Transport: rt}
}

// entryHostPort returns the host:port of a cluster entry URL exactly as it
// appears in the URLs git-sync builds from it (url.URL.Host), which is what
// clusterTransport.entryHosts is matched against.
func entryHostPort(rawURL string) (string, error) {
	u, err := url.Parse(rawURL)
	if err != nil {
		return "", fmt.Errorf("parse entry URL %q: %w", rawURL, err)
	}
	if u.Hostname() == "" {
		return "", fmt.Errorf("entry URL %q has no host", rawURL)
	}
	return u.Host, nil
}

// retryTransientFetch runs fn, retrying up to maxSyncAttempts on a transient
// git-fetch 404 — the same intermittent GitHub /info/refs failure the main
// sync loop absorbs (see isTransientGitFetchError). The default-branch
// recovery reuses it for its source-HEAD probe and its re-run replicate so a
// one-in-thirty blip on those extra GitHub reads is retried in-process rather
// than surfacing a raw "http 404" that the permanent-status classifier would
// promote to a terminal failure — the exact wedge the main loop's retry
// exists to prevent. A non-transient error returns immediately; a persistent
// transient error returns after the attempts are spent, matching the main
// loop's contract that an exhausted 404 is then permanent.
func retryTransientFetch[T any](ctx context.Context, fn func(context.Context) (T, error)) (T, error) {
	var zero T
	var lastErr error
	for attempt := 1; attempt <= maxSyncAttempts; attempt++ {
		if attempt > 1 {
			select {
			case <-ctx.Done():
				return zero, ctx.Err()
			case <-time.After(syncRetryDelay):
			}
		}
		v, err := fn(ctx)
		if err == nil {
			return v, nil
		}
		lastErr = err
		if !isTransientGitFetchError(err) {
			return zero, err
		}
	}
	return zero, lastErr
}

func targetBaseURLHost(rawURL string) (string, error) {
	u, err := url.Parse(rawURL)
	if err != nil {
		return "", fmt.Errorf("parse target URL %q: %w", rawURL, err)
	}
	// Check Hostname() rather than Host: a port-only form like "https://:8080"
	// gives Host=":8080" (non-empty) but Hostname()="" — which would silently
	// make hostInCluster always false and fail every push with 401.
	if u.Hostname() == "" {
		return "", fmt.Errorf("target URL %q has no host", rawURL)
	}
	return u.Hostname(), nil
}

func (s *syncer) sync(ctx context.Context, req syncRequest) error {
	sourceURL := s.sourceURL(req)
	targetURL := s.targetURL(req)

	ctx, span := Tracer().Start(ctx, "mirror.sync",
		trace.WithAttributes(
			attribute.String("entire.source_kind", string(req.kind())),
			attribute.String("entire.source_owner", req.SourceOwner),
			attribute.String("entire.source_repo", req.SourceRepo),
			attribute.String("entire.target_ulid", req.TargetULID),
			attribute.Int64("entire.installation_id", req.InstallationID),
			attribute.String("entire.source_url", sourceURL),
			attribute.String("entire.target_url", targetURL),
		),
	)
	defer span.End()

	slog.InfoContext(ctx, "Starting git-sync",
		slog.String("source_kind", string(req.kind())),
		slog.String("source", sourceURL),
		slog.String("target", targetURL),
		slog.Int64("installation_id", req.InstallationID),
	)

	auth, err := s.sourceAuth(ctx, req)
	if err != nil {
		span.SetAttributes(attribute.Int("entire.sync.attempts", 1))
		classified := classifySyncError(fmt.Errorf("resolving source auth: %w", err))
		span.RecordError(classified)
		span.SetStatus(otelcodes.Error, "source auth")
		return classified
	}

	// The token is minted once and reused across retries: the working theory
	// for the transient 404 is GitHub's eventual consistency between
	// api.github.com (where the token is minted) and github.com (where the
	// git fetch uses it). Waiting lets that token propagate. Re-minting
	// would reset the propagation clock with a fresh token, defeating the
	// purpose of the backoff.
	client := gitsync.New(gitsync.Options{
		HTTPClient:                    s.httpClientFor(req),
		BootstrapFallbackMaxPackBytes: s.bootstrapFallbackMaxPackBytes,
		Auth:                          auth,
		BootstrapLogger: slog.Default().With(
			slog.String("target_ulid", req.TargetULID),
			slog.String("source_owner", req.SourceOwner),
			slog.String("source_repo", req.SourceRepo)),
	})

	replicateReq := gitsync.SyncRequest{
		// An entiredb source cluster 307s /info/refs off a non-hosting
		// node exactly like the target does, so carry the redirect into
		// the endpoint for entiredb-kind fetches; GitHub never emits it
		// and keeps the plain endpoint.
		Source: gitsync.Endpoint{
			URL:                    sourceURL,
			FollowInfoRefsRedirect: req.entiredbSourced(),
		},
		// FollowInfoRefsRedirect carries the 307 from a non-hosting
		// entiredb node into the endpoint, so the subsequent
		// receive-pack POST lands on the hosting replica instead of
		// the originally-configured host. No-op for the current
		// node-specific ENTIRE_TARGET_URL (node1 either hosts or
		// serves via DISS), but lets us flip fleet to the cluster
		// entry domain without a code change.
		Target: gitsync.Endpoint{URL: targetURL, FollowInfoRefsRedirect: true},
		Scope:  refScopeFor(req),
		Policy: syncPolicyFor(req),
	}

	var (
		result  gitsync.SyncResult
		lastErr error
		attempt int
	)
	for attempt = 1; attempt <= maxSyncAttempts; attempt++ {
		if attempt > 1 {
			select {
			case <-ctx.Done():
				span.SetAttributes(attribute.Int("entire.sync.attempts", attempt-1))
				classified := transientErr(ctx.Err())
				reportSyncFailure(ctx, span, result, classified, ctx.Err(), req)
				span.SetStatus(otelcodes.Error, "context canceled during retry backoff")
				return classified
			case <-time.After(syncRetryDelay):
			}
		}

		result, err = client.Replicate(ctx, replicateReq)
		if err == nil {
			lastErr = nil
			break
		}
		lastErr = err
		if !isTransientGitFetchError(err) {
			break
		}
		if attempt >= maxSyncAttempts {
			break
		}
		slog.WarnContext(ctx, "Transient git-fetch failure; will retry",
			slog.Int("attempt", attempt),
			slog.Int("max_attempts", maxSyncAttempts),
			slog.Any("error", redactAuth(err)),
		)
	}

	span.SetAttributes(attribute.Int("entire.sync.attempts", attempt))

	// A prune delete rejected with entiredb's deny-current-branch reason
	// means the source renamed its default branch and the mirror's HEAD
	// hasn't followed: move HEAD via RepoAdmin.SetDefaultBranch, then
	// re-run the identical replicate in the same job so the stale branch
	// prunes immediately. This branch is terminal — recovery classifies its
	// own failures (a transient GitHub 404 during the probe/re-replicate is
	// retried in-process and stays transient; a non-convergent case such as
	// an excluded source HEAD or an RPC PermissionDenied is marked permanent
	// so it stops churning instead of redelivering forever) and returns them
	// directly, bypassing the generic classifier below. followed tracks that
	// HEAD was just ensured so the steady-state follow further down skips its
	// redundant RPC. Already-wedged mirrors heal on their next sync.
	followed := false
	if lastErr != nil && s.repoAdmin != nil && !req.namespaceScoped() {
		if rejectedRef, ok := isDenyCurrentBranchDeletion(lastErr); ok {
			span.SetAttributes(attribute.Bool("entire.sync.default_branch_recovery", true))
			recResult, ensuredHEAD, recErr := s.recoverDefaultBranchRename(ctx, req.TargetULID, rejectedRef,
				func(ctx context.Context) (string, error) {
					probe, perr := retryTransientFetch(ctx, func(ctx context.Context) (gitsync.ProbeResult, error) {
						return client.Probe(ctx, gitsync.ProbeRequest{Source: gitsync.Endpoint{URL: sourceURL}})
					})
					if perr != nil {
						return "", perr
					}
					return probe.SourceHEAD, nil
				},
				func(ctx context.Context) (gitsync.SyncResult, error) {
					return retryTransientFetch(ctx, func(ctx context.Context) (gitsync.SyncResult, error) {
						return client.Replicate(ctx, replicateReq)
					})
				},
			)
			if recErr != nil {
				classified := classifyRecoveryError(recErr)
				span.SetAttributes(attribute.String("entire.sync.default_branch_recovery_error", recoveryErrorCode(recErr)))
				reportSyncFailure(ctx, span, recoveryReportResult(recResult, result), classified, recErr, req)
				return classified
			}
			result = recResult
			lastErr = nil
			// Skip the steady-state follow only when the re-run confirmed the
			// source HEAD we just ensured. A source that switched its default
			// AGAIN mid-recovery shows a fresher SourceHEAD on the re-run's
			// result — fall through to the follow so it is applied now rather
			// than waiting for the next sync.
			followed = result.Execution.SourceHEAD == "" || result.Execution.SourceHEAD == ensuredHEAD
		}
	}

	if lastErr != nil {
		// No refs to apply is a clean no-op, not a failure: don't record it as
		// a span error and signal the noop disposition so disposeResult acks
		// rather than redelivering a job that can only repeat the same outcome
		// against an unchanged source. The reason is recorded but does NOT
		// change the disposition — every case here acks with no watermark. Only
		// the diverged case is a standing problem, and it is deliberately
		// surfaced through the counter and the span rather than through a
		// failed sync: redelivering it would repeat a refusal that no retry can
		// resolve, and terminating it would publish 'failed' for a mirror that
		// is perfectly clonable.
		if reason, ok := classifyEmptySource(lastErr, req.SourceRefsClaim, req.TargetRefsClaim); ok {
			// The reason alone is not enough to act on for the uncorroborated
			// family — one sentinel covers sub-cases with opposite remedies,
			// separated only by the wrapped message — so the error text rides
			// on the span and the log, redacted like every other surfaced
			// sync error.
			span.SetAttributes(
				attribute.Bool("entire.sync.noop", true),
				attribute.String("entire.sync.empty_source_reason", string(reason)),
				attribute.String("entire.sync.empty_source_error", redactAuth(lastErr).Error()),
			)
			span.SetStatus(otelcodes.Ok, "no source refs to apply")
			logEmptySource(ctx, reason, req, lastErr)
			s.metrics.recordEmptySource(ctx, reason, req.SourceClusterParent)
			return errSourceNoRefs
		}
		classified := classifySyncError(redactAuth(lastErr))
		reportSyncFailure(ctx, span, result, classified, lastErr, req)
		return classified
	}

	span.SetAttributes(
		attribute.Int("entire.refs.applied", result.Counts.Applied),
		attribute.Int("entire.refs.skipped", result.Counts.Skipped),
		attribute.Int("entire.refs.blocked", result.Counts.Blocked),
		attribute.Int("entire.refs.deleted", result.Counts.Deleted),
	)

	s.reportSyncSuccess(ctx, result, req)

	// Steady-state follow: a default-branch change to an already-existing
	// branch produces no data-plane push, so it only ever surfaces here —
	// as the source HEAD git-sync parsed during the sync. Idempotent
	// server-side and best-effort (a failure defers to the next sync);
	// skipped when the recovery path above already ensured HEAD.
	if !followed && !req.namespaceScoped() {
		s.followSourceHEAD(ctx, req.TargetULID, result.Execution.SourceHEAD)
	}

	return nil
}

// markSyncSpanResult records a failed sync on the mirror.sync span — except for
// a benign concurrent-ref race, which lost a compare-and-swap to a competing
// sync of the same repo and self-heals on the next delivery. A race is tagged
// entire.sync.raced (queryable, mirroring the mirror.consume carve-out) but left
// un-errored, so it never shows as a failed mirror.sync span or counts toward an
// error-rate query on this span — matching the outcome metric's nak+term
// numerator, which also excludes raced. Exhaustion is a delivery-count concept
// the syncer can't see; the consumer still escalates a race that burns through
// redelivery to an error on the parent mirror.consume span (see
// shouldMarkSpanError). The race check uses the raw error, not the
// redacted/classified one, so redactAuth flattening the chain can't defeat it.
func markSyncSpanResult(span trace.Span, classified, raw error) {
	if isConcurrentRefError(raw) {
		span.SetAttributes(attribute.Bool("entire.sync.raced", true))
		return
	}
	span.RecordError(classified)
	span.SetStatus(otelcodes.Error, "sync from github")
}

// recoveryReportResult picks which result is worth reporting when the
// default-branch reconcile fails.
//
// Every guard in recoverDefaultBranchRename that bails before re-running
// replicate returns a zero SyncResult, so reporting it would log empty
// execution attributes and erase the route of the sync that triggered the
// reconcile — the one fact reportSyncFailure exists to preserve. The re-run's
// result is preferred when it actually ran; otherwise the original failure's
// route stands, which is the sync an operator is trying to understand anyway.
func recoveryReportResult(recResult, original gitsync.SyncResult) gitsync.SyncResult {
	if recResult.Execution.OperationMode != "" {
		return recResult
	}
	return original
}

// reportSyncFailure preserves the execution route git-sync returns alongside
// a post-planning error. In particular, a failed batched bootstrap carries the
// route that selected bootstrap and the reason relay was unavailable; dropping
// the result here made those failures indistinguishable from an ordinary relay
// failure in both logs and traces.
func reportSyncFailure(ctx context.Context, span trace.Span, result gitsync.SyncResult, classified, raw error, req syncRequest) {
	span.SetAttributes(
		attribute.String("entire.sync.operation_mode", result.Execution.OperationMode),
		attribute.String("entire.sync.transfer_mode", result.Execution.TransferMode),
		attribute.String("entire.sync.relay_reason", result.Execution.Reason),
		attribute.Bool("entire.sync.batch.enabled", result.Execution.Batch.Enabled),
		attribute.Int("entire.sync.batch.planned", result.Execution.Batch.Planned),
		attribute.Int("entire.sync.batch.done", result.Execution.Batch.Done),
	)
	markSyncSpanResult(span, classified, raw)

	args := []any{
		slog.String("source_owner", req.SourceOwner),
		slog.String("source_repo", req.SourceRepo),
		slog.String("target_ulid", req.TargetULID),
		slog.String("operation_mode", result.Execution.OperationMode),
		slog.String("transfer_mode", result.Execution.TransferMode),
		slog.String("relay_reason", result.Execution.Reason),
		slog.Bool("batch_enabled", result.Execution.Batch.Enabled),
		slog.Int("batch_planned", result.Execution.Batch.Planned),
		slog.Int("batch_done", result.Execution.Batch.Done),
		slog.Any("error", classified),
	}
	if isConcurrentRefError(raw) {
		slog.WarnContext(ctx, "Git sync execution raced", args...)
		return
	}
	slog.ErrorContext(ctx, "Git sync execution failed", args...)
}

// kind returns the request's source kind, defaulting the zero value to
// github so pre-kind callers and tests keep their meaning.
func (r syncRequest) kind() gitjobs.SourceKind {
	if r.SourceKind == "" {
		return gitjobs.SourceKindGithub
	}
	return r.SourceKind
}

// entiredbSourced reports whether the source leg is an entiredb cluster: the
// job's own URL, cert-only auth, and a 307-following source endpoint.
func (r syncRequest) entiredbSourced() bool {
	return r.kind() == gitjobs.SourceKindEntireDB || r.kind() == gitjobs.SourceKindEntireDBNamespace
}

// namespaceScoped reports whether the sync replicates only the Entire-owned
// namespace onto a GitHub-mirror placement.
func (r syncRequest) namespaceScoped() bool {
	return r.kind() == gitjobs.SourceKindEntireDBNamespace
}

func (s *syncer) sourceURL(req syncRequest) string {
	if req.entiredbSourced() {
		// The job carries the full by-ID URL (validated at decode,
		// host-admitted by the consumer); nothing to compose.
		return req.SourceURL
	}
	return fmt.Sprintf("%s/%s/%s", s.sourceBaseURL, req.SourceOwner, req.SourceRepo)
}

// reportSyncSuccess records a completed sync's outcome: the log line, and for a
// converged empty pair the counter reason that says the placement healed.
//
// Extracted from sync() for one reason — nothing could test it there. The
// converged branch is the only reason this change exists, and it is invisible
// to the compiler and to every existing test: deleting it left the whole suite
// green, because the position still gets stamped by the ordinary success path
// (err == nil), so the only casualties were the counter and the log. Those are
// exactly the signal COR-1300 was filed to produce, and they would have gone
// quiet with nothing failing.
//
// Takes the span from ctx rather than as a parameter so a test can call it with
// a plain context and get a no-op span, matching the replicate-thunk seam
// recoverDefaultBranchRename already uses for the same reason.
func (s *syncer) reportSyncSuccess(ctx context.Context, result gitsync.SyncResult, req syncRequest) {
	if result.Execution.Converged {
		// Source asserted empty, target asserted empty, and git-sync
		// corroborated both in one session: converged with nothing to apply.
		// Reported as a real success rather than a no-op BECAUSE the coverage
		// is provable, which is what lets the completion carry a write
		// position — the thing that clears a resync flag on a repo that was
		// created and never pushed to.
		trace.SpanFromContext(ctx).SetAttributes(attribute.Bool("entire.sync.converged", true))
		s.metrics.recordEmptySource(ctx, emptyReasonConverged, req.SourceClusterParent)
		slog.InfoContext(ctx, "Sync complete: source and target both empty, nothing to mirror",
			slog.String("source_owner", req.SourceOwner),
			slog.String("source_repo", req.SourceRepo),
			slog.String("target_ulid", req.TargetULID),
		)
		return
	}
	slog.InfoContext(ctx, "Sync complete",
		slog.String("source_owner", req.SourceOwner),
		slog.String("source_repo", req.SourceRepo),
		slog.String("target_ulid", req.TargetULID),
		slog.Int("applied", result.Counts.Applied),
		slog.Int("skipped", result.Counts.Skipped),
		slog.Int("blocked", result.Counts.Blocked),
		slog.Int("deleted", result.Counts.Deleted),
		// The strategy git-sync actually chose. Routing decisions (replicate
		// vs bootstrap vs bootstrap resume) were previously invisible here,
		// which is why ENT-2054 took a code read instead of a log query.
		slog.String("operation_mode", result.Execution.OperationMode),
		slog.String("transfer_mode", result.Execution.TransferMode),
		slog.String("relay_reason", result.Execution.Reason),
	)
}

// refScopeFor builds the ref scope for one request. Extracted alongside
// syncPolicyFor because AllRefs is not merely this worker's preference: it is a
// precondition git-sync enforces for the empty-source policy (under a narrower
// scope the source listing is itself narrowed, so an empty result says nothing
// about the repository), and a scope built inline in the config literal is one
// no test can read.
func refScopeFor(req syncRequest) gitsync.RefScope {
	return gitsync.RefScope{
		AllRefs: true,
		// refs/pull/* is GitHub's PR ref namespace — skip mirroring it
		// to avoid surfacing source-side PR state on the mirror.
		//
		// refs/heads/trunk-merge/* and refs/heads/gh-readonly-queue/*
		// are ephemeral merge-queue refs (trunk-merge keyed by PR number
		// + a per-attempt UUID; gh-readonly-queue is GitHub's native
		// merge-queue namespace, refs/heads/gh-readonly-queue/<base>/
		// pr-<n>-<sha>): created and deleted within minutes, so mirroring
		// them is pure churn. Because each is brand-new, git-sync plans a
		// create (target hash zero) that races a concurrent webhook or the
		// re-kicker and draws entire-server's create-side CAS rejection
		// ("already exists"). They carry no value on the mirror, so we drop
		// them at the source rather than push and prune the churn. (The
		// create-race misclassification itself is now fixed upstream:
		// git-sync classifies "already exists" as ErrTargetRefMoved — the
		// create-side analog of "remote ref has changed" — so a create race
		// that still slips through routes to dispositionRaced like any
		// concurrent-ref miss rather than a hard sync failure; see
		// isConcurrentRefError. This exclusion just removes the dominant
		// source of those redeliveries.)
		//
		// The remaining prefixes mirror entiredb's reserved-push denylist
		// (the reservedPrefixes/reservedExact sets in its refpolicy
		// package, applied by server/githttp receive-pack):
		// git-receive-pack returns 403 "push to <ref> is not allowed"
		// for any of these namespaces. Under AllRefs we faithfully copy
		// whatever the source advertises, so a stray ref like
		// refs/remotes/origin/* accidentally pushed up to a source repo
		// would otherwise fail the entire sync permanently. Excluding
		// the prefixes here means we neither read them from the source
		// nor try to push/prune them on the target.
		//
		// refs/tlog/* is entiredb-owned (commit-tlog state appended by
		// entire-server on its receive-pack hook); direct pushes are
		// rejected with "use sync instead".
		//
		// Per-kind: an entiredb source (native mirroring) additionally
		// syncs the unmirrored namespace — see excludeRefPrefixesFor.
		ExcludeRefPrefixes: excludeRefPrefixesFor(req.kind()),
		// Exact-match reservations (not prefixes): skip the bare
		// directory-anchor refs entiredb blocks, without excluding
		// their mirrored children (refs/heads/entire/a still syncs).
		ExcludeRefs: excludeRefsFor(req.kind()),
		// The namespace kind is scoped by inclusion: every ref outside the
		// Entire-owned namespace is neither pushed nor pruned, whatever the
		// payload claims.
		IncludeRefPrefixes: includeRefPrefixesFor(req.kind()),
	}
}

// syncPolicyFor builds the git-sync policy for one request. Extracted from the
// config literal so the empty-source wiring is unit-testable: every field here
// is a plain bool with a defaulted-off zero value, so dropping any one of them
// compiles, passes, and silently turns the policy off — which is exactly how
// the first version of this shipped inert (AllowEmptySource set, the two
// assertions it requires never supplied).
func syncPolicyFor(req syncRequest) gitsync.SyncPolicy {
	// entiredb-kind only, for both halves of the empty-source policy. The
	// distinction is only sound where a data plane can answer for the
	// repository's ref state, and the watermark it feeds exists solely for
	// native mirrors — a GitHub source gains nothing and would have its
	// empty-repo syncs reclassified from no-op to ref-applying success,
	// moving last_success_unix and pruning the failure index on a sync that
	// applied nothing.
	// The namespace kind is excluded with GitHub: it takes no position
	// snapshot, so it can assert nothing about either leg.
	native := req.kind() == gitjobs.SourceKindEntireDB
	return gitsync.SyncPolicy{
		IncludeTags: true,
		Prune:       true,
		// Ask git-sync to separate "the source has no refs" from "the scope
		// selected none of them", and to treat a source and target both
		// VERIFIED empty as the converged state they are rather than an
		// error. That converged sync stamps a write position, which is what
		// lets entire-core's resync sweep clear a flag on a repo that was
		// created and never pushed to (COR-1300); without it the placement is
		// flagged behind forever, since a no-op completion carries no
		// watermark and the flag can never be satisfied.
		AllowEmptySource: native,
		// An owner that deleted its last namespace branch advertises refs but
		// none in scope; without this the replicas keep serving a branch the
		// owner no longer has.
		AllowEmptyScope: req.namespaceScoped(),
		// The assertions git-sync requires before it will call anything
		// converged: it cannot determine emptiness itself on either leg,
		// because ref hiding is invisible to a client and configured
		// independently per leg, so an empty advertisement and a repository
		// full of hidden refs are the same observation. They come from
		// RepoAdmin.GetWritePosition on each side, read before the fetch (see
		// syncRequest).
		//
		// git-sync treats them as necessary and never sufficient: it still
		// requires an empty advertisement on each leg, an unborn HEAD on the
		// source, and no visible in-scope target ref, and each of those checks
		// can only refuse. So a wrong assertion cannot manufacture a
		// convergence out of a populated repository — but a MISSING one
		// (every read failure lands there) does forfeit a real convergence,
		// which is the direction to fail in.
		//
		// Gated on native as well, so a GitHub request carrying stray
		// assertions cannot half-enable a policy whose other half is off.
		SourceAssertedEmpty: native && req.sourceAssertedEmpty(),
		TargetAssertedEmpty: native && req.targetAssertedEmpty(),
	}
}

func (s *syncer) targetURL(req syncRequest) string {
	return fmt.Sprintf("%s/git/repo/%s", s.targetBaseURL, req.TargetULID)
}

// sourceAuth returns a gitsync.AuthProvider for the source endpoint.
// entiredb sources never mint: the worker's client certificate is the whole
// credential (the source cluster's svctok listener grants the workload
// cert-only cluster-wide pull), and clusterTransport already routes the
// fetch onto the mTLS round-tripper — a nil provider attaches no header.
// For GitHub, returns nil when the job has no installation ID or the App
// client is not configured — callers fall through to anonymous GitHub
// access for public repos.
func (s *syncer) sourceAuth(ctx context.Context, req syncRequest) (gitsync.AuthProvider, error) {
	if req.entiredbSourced() {
		return nil, nil
	}
	if req.InstallationID == 0 || s.githubApp == nil {
		return nil, nil
	}

	ctx, span := Tracer().Start(ctx, "mirror.source_auth",
		trace.WithAttributes(
			attribute.Int64("entire.installation_id", req.InstallationID),
			attribute.String("entire.source_repo", req.SourceRepo),
		),
	)
	defer span.End()

	// Time exactly the mint round-trip. This is the most actionable git-op
	// breakdown leg (a synchronous entire-core STS call on every authenticated
	// sync) and the before/after baseline for COR-596 token caching. Tagged
	// ok|error only — the failure breakdown lives on this span, not the metric.
	start := time.Now()
	token, err := s.githubApp.InstallationToken(ctx, req.TargetULID, req.SourceOwner, req.SourceRepo, req.InstallationID)
	if err != nil {
		s.metrics.recordSourceAuth(ctx, sourceAuthOutcomeError, time.Since(start))
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "installation token")
		// Returned unwrapped exactly as before: the sole caller (sync) wraps it
		// with "resolving source auth: %w" and runs it through classifySyncError,
		// and the token-leak guard (TestSyncDoesNotLeakInstallationToken) depends
		// on that path — re-wrapping here would change the error text under it for
		// no benefit.
		return nil, err
	}
	s.metrics.recordSourceAuth(ctx, sourceAuthOutcomeOK, time.Since(start))
	return gitsync.StaticAuthProvider{
		Source: gitsync.EndpointAuth{Username: "x-access-token", Token: token},
	}, nil
}

// Package failindex maintains the mirror-sync failure index: a JetStream KV
// bucket that records repos whose git-sync terminally failed, keyed by the
// entiredb mirror ULID, so a paced re-kicker can re-drive them. See
// docs/design/mirror-sync-failure-index.md.
//
// The worker is the sole writer: RecordFailure on a terminal failure (a CAS
// upsert with a per-repo attempt counter, deduplicated by the originating
// stream sequence), and ClearOnSuccess when a later sync for the repo succeeds.
// The package depends only on nats.go and stores the original job subject and
// payload verbatim — it never decodes them — so it stays out of the gen/proto
// import graph (the dependency that reverted #109).
package failindex

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nuid"
)

// Version1 is the current FailedSync schema version.
const Version1 = 1

// DefaultBucket is the KV bucket name, declared in fleet (apps/nats-streams).
const DefaultBucket = "mirror_sync_failed"

// RekickHeader is the NATS header the re-kicker (cmd/rekicker) stamps on a
// re-emitted job. The worker reads it on a successful sync to tag the clear
// cleared{via=rekick} vs cleared{via=normal}. It is ONLY a metric tag —
// clearing happens on any success regardless — so the index never depends on
// the re-kicker to prune repos that healed on their own. Shared here because
// both cmd/worker (reader) and cmd/rekicker (writer) need the exact string.
const RekickHeader = "Mirror-Rekick"

// RekickMsg builds the re-emit message for a stored failure: the stored job
// payload republished verbatim to its stored subject, stamped with
// RekickHeader (so the worker tags the eventual clear as via=rekick) and a
// FRESH Nats-Msg-Id (so the re-emit is NOT collapsed by the stream's dedup
// window against the original or a prior re-kick — it must be delivered and
// retried). Shared by the automated re-kicker (cmd/rekicker) and the operator
// CLI (mirror-pipeline-admin failindex rekick) so the two cannot drift on the
// wire contract.
func RekickMsg(ulid string, fs FailedSync) *nats.Msg {
	msg := nats.NewMsg(fs.Subject)
	msg.Data = fs.Payload
	msg.Header.Set(RekickHeader, ulid)
	msg.Header.Set(nats.MsgIdHdr, nuid.Next())
	return msg
}

// FailureReason classifies why a job was dead-ended (low cardinality).
type FailureReason string

const (
	ReasonPermanent     FailureReason = "permanent"      // a permanent sync error
	ReasonMaxDeliveries FailureReason = "max_deliveries" // exhausted the consumer's MaxDeliver
	ReasonValidation    FailureReason = "validation"     // a pre-sync validation reject
)

// Source identifies the code path that recorded the entry (low cardinality).
const (
	SourceWorkerCompletion = "worker_completion" // sync succeeded; ready publication exhausted deliveries
	SourceWorkerPermanent  = "worker_permanent"
	SourceWorkerValidation = "worker_validation"
	SourceWorkerExhausted  = "worker_exhausted" // MaxDeliver exhausted (in-process pre-emption)
	SourceAdvisory         = "advisory"         // the MAX_DELIVERIES/MSG_TERMINATED backstop
)

// CorruptOp identifies which write path hit a stored entry whose JSON could not
// be unmarshalled (corruption, or a pre-Version1 schema). Both paths are
// fail-safe — RecordFailure overwrites the bad entry fresh, ClearOnSuccess
// leaves it untouched — but that recovery is otherwise invisible, so the worker
// wires a handler (WithCorruptHandler) to count + log it.
type CorruptOp string

const (
	// CorruptOpRecord: RecordFailure found an unreadable entry and overwrote it
	// fresh — the repo's prior Attempts / FirstSeen triage history is lost.
	CorruptOpRecord CorruptOp = "record"
	// CorruptOpClear: ClearOnSuccess found an unreadable entry and left it in
	// place (it can't prove the success is newer than the recorded failure).
	CorruptOpClear CorruptOp = "clear"
)

// FailedSync is the value stored per repo (keyed by mirror ULID). Subject +
// Payload are enough to republish an exact-equivalent job; the rest is triage
// metadata. LastSeq is the originating mirror_git_v1 stream sequence of the
// last counted failure — the dedup token that makes Attempts count distinct
// failing jobs rather than distinct writes.
type FailedSync struct {
	Version   int           `json:"version"`
	Subject   string        `json:"subject"`
	Payload   []byte        `json:"payload"`
	Reason    FailureReason `json:"reason"`
	Source    string        `json:"source"`
	LastError string        `json:"last_error,omitempty"`
	Attempts  int           `json:"attempts"`
	LastSeq   uint64        `json:"last_seq"`
	FirstSeen time.Time     `json:"first_seen"`
	LastSeen  time.Time     `json:"last_seen"`
}

// kvStore is the subset of nats.KeyValue the index uses; it is the test seam.
type kvStore interface {
	Get(key string) (nats.KeyValueEntry, error)
	Create(key string, value []byte) (uint64, error)
	Update(key string, value []byte, last uint64) (uint64, error)
	Delete(key string, opts ...nats.DeleteOpt) error
	WatchAll(opts ...nats.WatchOpt) (nats.KeyWatcher, error)
}

// defaultCASRetries bounds the optimistic-concurrency retry loop. Several writers
// can target one repo key at once: a worker replica's in-process write plus the
// advisory backstop, which fans its delivery out across a worker pool. A few
// retries is still ample — a committed Update raises LastSeq, so every lower-seq
// writer then short-circuits on the seq<=LastSeq no-op instead of retrying, and
// same-repo jobs are collapsed within the publish-time dedup window, so same-key
// contention stays well under the budget in practice.
const defaultCASRetries = 5

// Index is the failure index, bound to an existing KV bucket.
type Index struct {
	kv         kvStore
	casRetries int
	// onCorrupt, when set, is called whenever a write path hits an unreadable
	// stored entry (see CorruptOp). nil by default; wired via WithCorruptHandler.
	onCorrupt func(ulid string, op CorruptOp)
}

// Option configures an Index at Open time.
type Option func(*Index)

// WithCorruptHandler registers a callback invoked whenever a write path hits an
// unreadable stored entry (see CorruptOp). It keeps this package free of any
// metrics/logging dependency: the worker passes a handler that increments
// mirror.sync.failed_index.corrupt_reset{op} and logs the ULID. The handler runs
// inline on the write path, so it must be cheap and non-blocking.
func WithCorruptHandler(fn func(ulid string, op CorruptOp)) Option {
	return func(ix *Index) { ix.onCorrupt = fn }
}

// WithMaxEntryAge is retained for source compatibility.
// Deprecated: unresolved failures no longer expire; bound retries in the reader.
func WithMaxEntryAge(time.Duration) Option { return func(*Index) {} }

// WithEvictHandler is retained for source compatibility.
// Deprecated: unresolved failures are never evicted by age.
func WithEvictHandler(func(string, time.Duration)) Option { return func(*Index) {} }

// Open binds to the KV bucket, which must already exist — it is declared in
// fleet (apps/nats-streams) and reconciled by nack; binaries never create it.
func Open(js nats.JetStreamContext, bucket string, opts ...Option) (*Index, error) {
	kv, err := js.KeyValue(bucket)
	if err != nil {
		return nil, fmt.Errorf("failindex: bind kv bucket %q: %w", bucket, err)
	}
	ix := &Index{kv: kv, casRetries: defaultCASRetries}
	for _, opt := range opts {
		opt(ix)
	}
	return ix, nil
}

// RecordFailure upserts the entry for ulid, incrementing Attempts once per
// distinct originating sequence (seq). It is idempotent for a repeated
// (ulid, seq), so the in-process path and the advisory backstop recording the
// same terminal failure do not double-count. fs supplies Subject, Payload,
// Reason and Source; the counter and timestamp fields are managed here. now is
// injected for testability.
//
// recorded reports whether this call actually created or updated an entry. It is
// false on a dedup/reorder no-op (seq <= LastSeq), where the failure was already
// captured by an earlier or concurrent write. Callers should increment their
// "recorded" metric only when recorded is true, so a redelivery (or the
// in-process/advisory pair) doesn't inflate it. On a non-nil error nothing was
// written and recorded is false.
func (ix *Index) RecordFailure(ulid string, fs FailedSync, seq uint64, now time.Time) (recorded bool, err error) {
	return ix.recordFailure(ulid, fs, seq, now, false)
}

// RecordNoopCompletionFailure captures a failed ready publication after a noop.
// A noop does not reconcile refs: preserve any existing non-completion failure
// (including unreadable evidence) instead of making it eligible for noop cleanup.
func (ix *Index) RecordNoopCompletionFailure(ulid string, fs FailedSync, seq uint64, now time.Time) (bool, error) {
	if fs.Source != SourceWorkerCompletion {
		return false, errors.New("failindex: noop completion must use worker_completion source")
	}
	return ix.recordFailure(ulid, fs, seq, now, true)
}

func (ix *Index) recordFailure(ulid string, fs FailedSync, seq uint64, now time.Time, preserveSyncFailure bool) (recorded bool, err error) {
	if ulid == "" {
		return false, errors.New("failindex: empty ulid")
	}
	for attempt := 0; attempt <= ix.casRetries; attempt++ {
		entry, gErr := ix.kv.Get(ulid)
		switch {
		case errors.Is(gErr, nats.ErrKeyNotFound):
			v := fs
			v.Version = Version1
			v.Attempts = 1
			v.LastSeq = seq
			v.FirstSeen = now
			v.LastSeen = now
			data, mErr := json.Marshal(v)
			if mErr != nil {
				return false, fmt.Errorf("failindex: marshal %s: %w", ulid, mErr)
			}
			if _, cErr := ix.kv.Create(ulid, data); cErr != nil {
				if errors.Is(cErr, nats.ErrKeyExists) {
					continue // a concurrent writer created it first — retry as update
				}
				return false, fmt.Errorf("failindex: create %s: %w", ulid, cErr)
			}
			return true, nil
		case gErr != nil:
			return false, fmt.Errorf("failindex: get %s: %w", ulid, gErr)
		}

		var cur FailedSync
		corrupt := false
		if uErr := json.Unmarshal(entry.Value(), &cur); uErr != nil {
			// Unreadable entry (corruption / older schema): start fresh rather
			// than wedge — the CAS Update below still guards the write. Defer the
			// onCorrupt report until the overwrite actually commits: a reset entry
			// has LastSeq 0, so a degenerate seq==0 call would otherwise report a
			// reset the no-op below never performed.
			cur = FailedSync{FirstSeen: now}
			corrupt = true
		}
		if preserveSyncFailure && (corrupt || cur.Source != SourceWorkerCompletion) {
			return false, nil
		}
		if seq <= cur.LastSeq {
			// Already counted (== — the in-process path and the advisory backstop
			// recording the same message), or an out-of-order OLDER failure (< —
			// a lower-seq same-repo job recorded after a higher-seq one, possible
			// across concurrent worker replicas). Never move LastSeq backwards:
			// ClearOnSuccess trusts it as "the newest recorded failure", so a
			// regressed LastSeq would let an intermediate success wipe a newer
			// failure from the index. Stream seqs are monotonic, so the newest
			// failure always has the highest seq. (Attempts under-counts the rare
			// reorder — acceptable; it is triage-only.) No new entry → recorded=false.
			return false, nil
		}
		cur.Version = Version1
		cur.Subject = fs.Subject
		cur.Payload = fs.Payload
		cur.Reason = fs.Reason
		cur.Source = fs.Source
		cur.LastError = fs.LastError
		cur.Attempts++
		cur.LastSeq = seq
		cur.LastSeen = now
		if cur.FirstSeen.IsZero() {
			cur.FirstSeen = now
		}
		data, mErr := json.Marshal(cur)
		if mErr != nil {
			return false, fmt.Errorf("failindex: marshal %s: %w", ulid, mErr)
		}
		if _, uErr := ix.kv.Update(ulid, data, entry.Revision()); uErr != nil {
			if errors.Is(uErr, nats.ErrKeyExists) {
				continue // CAS conflict — another write landed; re-read and retry
			}
			return false, fmt.Errorf("failindex: update %s: %w", ulid, uErr)
		}
		if corrupt && ix.onCorrupt != nil {
			// The unreadable entry was actually overwritten just now — its prior
			// Attempts/FirstSeen history is lost, so surface it. Fires exactly once
			// per call (this is the sole success path), and never on the seq<=LastSeq
			// no-op or a CAS-conflict retry that re-reads a readable entry.
			ix.onCorrupt(ulid, CorruptOpRecord)
		}
		return true, nil
	}
	return false, fmt.Errorf("failindex: record %s exhausted %d CAS retries", ulid, ix.casRetries)
}

// ClearOnSuccess removes the entry for ulid after a successful sync, provided
// the success is at least as new as the last recorded failure (successSeq >=
// LastSeq) so an older success cannot wipe a newer recorded failure. It is a
// no-op when the repo is not in the index (the common case). The delete is
// revision-guarded, so a failure write that lands between the Get and the
// Delete is preserved. Returns whether an entry was actually removed (for the
// cleared{via} metric). Clearing is best-effort: callers should log an error
// but must not fail the sync (it already succeeded; a stale entry self-heals on
// the next success or re-kick).
func (ix *Index) ClearOnSuccess(ulid string, successSeq uint64) (bool, error) {
	return ix.clearOnSuccess(ulid, successSeq, false)
}

// ClearOnCompletion removes only a completion-publication failure after a ready
// publication succeeds. The source and sequence checks use the same KV revision
// as the conditional delete, so a concurrent sync failure cannot be erased.
func (ix *Index) ClearOnCompletion(ulid string, successSeq uint64) (bool, error) {
	return ix.clearOnSuccess(ulid, successSeq, true)
}

func (ix *Index) clearOnSuccess(ulid string, successSeq uint64, completionOnly bool) (bool, error) {
	if ulid == "" {
		return false, errors.New("failindex: empty ulid")
	}
	entry, err := ix.kv.Get(ulid)
	if errors.Is(err, nats.ErrKeyNotFound) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("failindex: get %s: %w", ulid, err)
	}
	var cur FailedSync
	if uErr := json.Unmarshal(entry.Value(), &cur); uErr != nil {
		// Unreadable entry: we can't verify this success is newer than the
		// recorded failure, so don't delete it on a possibly-older success —
		// leave it for RecordFailure to overwrite (which recovers from
		// corruption) or for explicit cleanup. The clear path must not be the
		// one that destroys a corrupt-but-possibly-newer entry.
		if ix.onCorrupt != nil {
			ix.onCorrupt(ulid, CorruptOpClear)
		}
		return false, nil
	}
	if completionOnly && cur.Source != SourceWorkerCompletion {
		return false, nil
	}
	if successSeq < cur.LastSeq {
		return false, nil // a newer failure is recorded — leave it for its own success
	}
	if dErr := ix.kv.Delete(ulid, nats.LastRevision(entry.Revision())); dErr != nil {
		if errors.Is(dErr, nats.ErrKeyExists) {
			return false, nil // revision moved under us — a newer write won; skip
		}
		return false, fmt.Errorf("failindex: delete %s: %w", ulid, dErr)
	}
	return true, nil
}

// Keys returns the ULIDs currently held in the index — live keys only
// (tombstones from cleared repos are excluded). An empty index returns an empty
// slice and a nil error. The re-kicker (PR 2) lists these and re-drives each so
// stuck repos re-sync and self-clear.
//
// ctx bounds the listing. nats.go's KeyValue.Keys() takes no context, and a
// WatchAll replay over a large index is unbounded — so without this the
// re-kicker's pass deadline / SIGTERM could not interrupt the listing, which
// runs before the publish loop and is slowest exactly when the index is largest
// (post-outage). We drive the watcher directly and bail on ctx.Done(); Stop()
// removes the server-side ephemeral consumer on every return (a client dispatch
// goroutine left blocked on the watcher's internal buffer after a mid-stream
// cancel of a >256-key listing is reclaimed at process exit — safe because the
// re-kicker is a run-to-completion CronJob; drain w.Updates() after Stop() if
// ever reused in a long-lived process). Read path: needs $JS.API.> (watch
// consumer-create + direct get) + SUBSCRIBE _INBOX.> (delivery), no $KV write.
func (ix *Index) Keys(ctx context.Context) ([]string, error) {
	// IgnoreDeletes + MetaOnly mirror nats.go's own Keys(): live keys only, no
	// payload fetch.
	w, err := ix.kv.WatchAll(nats.IgnoreDeletes(), nats.MetaOnly())
	if err != nil {
		return nil, fmt.Errorf("failindex: watch keys: %w", err)
	}
	defer func() { _ = w.Stop() }()

	var keys []string
	// onSentinel handles nats.go's explicit nil "initial set fully delivered"
	// sentinel — the ONLY signal that denotes a genuinely complete listing. A
	// stalled replay enqueues ErrKeyWatcherTimeout on Error() BEFORE that sentinel
	// (the lone path that ever writes the watcher's errCh), so surface it as an
	// incomplete listing; otherwise the keys collected so far ARE the whole live
	// index. (A bare channel close WITHOUT a sentinel is handled separately below.)
	onSentinel := func() ([]string, error) {
		if werr := watcherErr(w); werr != nil {
			return nil, fmt.Errorf("failindex: keys: incomplete listing: %w", werr)
		}
		return keys, nil
	}

	for {
		select {
		case <-ctx.Done():
			// Deadline / SIGTERM fired. Don't discard a listing that ALSO just
			// completed (sentinel queued) to a simultaneous cancel — select picks
			// randomly among ready cases. Drain one item: ONLY the explicit nil
			// sentinel means the initial set was fully delivered (return the keys); a
			// real entry, or a bare channel close, means it wasn't complete, so honor
			// the cancellation (the keys are an incomplete prefix and must be dropped).
			select {
			case entry, ok := <-w.Updates():
				if ok && entry == nil {
					return onSentinel()
				}
			default:
			}
			return nil, fmt.Errorf("failindex: keys: %w", ctx.Err())
		case entry, ok := <-w.Updates():
			if !ok {
				// Updates closed WITHOUT a preceding nil sentinel: nats.go's pDone tore
				// the watcher down mid-listing (connection drop / reconnect exhaustion /
				// a non-retryable ordered-consumer recreate) and Stopped the init timer
				// first, so errCh is closed EMPTY — the close itself is the only
				// incompleteness signal (a normal/timed-out completion always delivers a
				// sentinel first, so we'd have returned via onSentinel). Returning the
				// prefix collected so far as the whole index would starve the tail on
				// re-kick while exiting healthy, so fail the listing loud — the next
				// tick retries.
				return nil, fmt.Errorf("failindex: keys: incomplete listing: watcher closed before the initial set completed (%d keys collected)", len(keys))
