// enqueues ErrKeyWatcherTimeout on Error() BEFORE sending the nil sentinel, so
// once Keys observes the sentinel that error is already readable; a normal
// "caught up" completion leaves Error() empty. NB this is the ONLY path that
// writes errCh — a teardown-driven close (pDone) leaves it empty, which is why
// Keys treats a sentinel-less channel close as incomplete on its own.
func watcherErr(w nats.KeyWatcher) error {
	select {
	case err := <-w.Error():
		return err
	default:
		return nil
	}
}

// Get returns the stored entry for ulid. found is false (with a nil error) when
// the repo is not in the index — e.g. it healed and was cleared between a Keys()
// listing and this read, which the re-kicker treats as a benign skip. A stored
// value that won't unmarshal returns an error: unlike the write paths (which
// overwrite a corrupt entry fresh), a reader has no fresh value to recover with.
func (ix *Index) Get(ulid string) (fs FailedSync, found bool, err error) {
	fs, _, found, err = ix.GetWithRevision(ulid)
	if err != nil {
		found = false
	}
	return
}

// GetWithRevision returns the revision that must accompany an operator resolution.
func (ix *Index) GetWithRevision(ulid string) (FailedSync, uint64, bool, error) {
	entry, err := ix.kv.Get(ulid)
	if errors.Is(err, nats.ErrKeyNotFound) {
		return FailedSync{}, 0, false, nil
	}
	if err != nil {
		return FailedSync{}, 0, false, fmt.Errorf("failindex: get %s: %w", ulid, err)
	}
	var fs FailedSync
	if err := json.Unmarshal(entry.Value(), &fs); err != nil {
		return FailedSync{}, entry.Revision(), true, fmt.Errorf("failindex: unmarshal %s: %w", ulid, err)
