	return fs, entry.Revision(), true, nil
}

// Resolve removes exactly the observation reviewed by an operator.
func (ix *Index) Resolve(ulid string, revision uint64) error {
	if ulid == "" || revision == 0 {
		return errors.New("failindex: key and nonzero revision required")
	}
	if err := ix.kv.Delete(ulid, nats.LastRevision(revision)); err != nil {
		return fmt.Errorf("failindex: resolve %s revision %d: %w", ulid, revision, err)
	}
	return nil
}

