func run() (retErr error) {
	// SIGTERM must SETTLE the in-flight sync, not cancel it. The root context is
	// therefore deliberately NOT signal-cancelled (it was, via NotifyContext):
	// the watcher below closes fetch admission through the very same drain the
	// operator endpoint uses, waits for the handler to settle, and only then
	// cancels. Until this existed, a KEDA scale-down cancelled a sync that could
	// be minutes into a clone — nothing was lost, because JetStream redelivers
	// and the advisory backstop records it, but the work was repeated and the
	// retry landed during the very burst that triggered the scale event
	// (ENT-2344). The health listener keeps serving throughout, so /readyz
	// reports 503 via drain.isPaused() while the settle runs.
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, os.Interrupt, syscall.SIGTERM)
	defer signal.Stop(sigCh)

	// Populated once the consumer exists. A signal arriving during startup finds
	// nil and tears down immediately, exactly as before — there is no in-flight
	// sync to protect yet.
	var shutdownDrain atomic.Pointer[consumerDrain]
	drainBudget := parseDurationEnv("ENTIRE_WORKER_SHUTDOWN_DRAIN_TIMEOUT", defaultShutdownDrainBudget)
	go settleThenCancel(ctx, sigCh, &shutdownDrain, drainBudget, cancel)

	mirrorCfg, err := loadMirrorConsumerConfig(os.Getenv)
	if err != nil {
		return err
	}
	slog.SetDefault(slog.Default().With("worker_role", mirrorCfg.subscription.role, "durable", mirrorCfg.subscription.durable))

	// Name this service in git-sync's User-Agent and git-protocol agent=
	// capability: "mirror-worker/<sha> git-sync/<ver> go-git/<ver>". Without
	// it, pushes are attributed to the bare library ("git-sync/dev ...") in
	// server access logs and APM.
	gitsync.SetIdentity("mirror-worker", version.Version)

	otelShutdown, err := otelsetup.Setup(ctx, otelsetup.Config{
		ServiceName:    "mirror-worker",
